import { useAuth } from "@/_core/hooks/useAuth";
import { startLogin } from "@/const";
import { useTheme } from "@/contexts/ThemeContext";
import { createFullBackup, parseFullBackup } from "@/lib/fullBackup";
import { filterCalendarDayTransactions } from "@/lib/calendarDetails";
import { trpc } from "@/lib/trpc";
import {
  exportJson,
  createLocalTransaction,
  filterLocalTransactions,
  filterLocalTransactionsByInvoiceMonth,
  loadLocalTransactions,
  isInvestmentExpense,
  parseExcelTransactions,
  parseBackupJson,
  sortTransactionsByDate,
  type LocalTransaction,
  type PaymentMethod,
} from "@/lib/localTransactions";
import { appendInvestmentOperation, applyInvestmentQuote, createLocalInvestment, filterInvestmentsByInstitution, investmentAccruedValue, investmentCategories, investmentCost, investmentInstitutionAllocations, investmentInstitutionCatalog, investmentMarketValue, investmentPerformanceHistory, investmentProfitability, investmentValueAtDate, loadLocalInvestments, normalizeInstitutionName, recalculateConsolidatedInvestment, recordDailyInvestmentHistory, removeInvestmentOperation, updateInvestmentOperation, type ContractedBenchmark, type InvestmentCategory, type LocalInvestment, type InvestmentOperationType } from "@/lib/localInvestments";
import { applyCreditPurchase, createLocalCreditCard, creditCardPurchaseInvoiceMonth, deleteLocalCreditCard, loadLocalCreditCards, removeCreditPurchase, setCreditCardInvoicePaid, updateLocalCreditCard, type CreditCard } from "@/lib/localCreditCards";
import { type DashboardWidgetKey } from "@/lib/dashboardPreferences";
import { addLocalCategory, deleteLocalCategory, isDefaultCategory, loadLocalCategories, updateLocalCategory, type LocalCategory } from "@/lib/localCategories";
import CreditCardsPage, { NextInvoiceCard, type CreditCardForm } from "@/pages/CreditCardsPage";
import BudgetPage, { type BudgetDraft } from "@/pages/BudgetPage";
import InvestmentOperationCardActions from "@/components/InvestmentOperationCardActions";
import { budgetCategoriesForMonth, budgetDueAlert, copyPreviousMonthBudget, createMonthlyBudget, loadLocalBudgets, recoverLocalBudgets, removeMonthlyBudget, saveLocalBudgets, updateMonthlyBudget, type MonthlyBudget } from "@/lib/localBudgets";
import { Button } from "@/components/ui/button";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { recordAuthEvent } from "@/lib/authEvents";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Tooltip as UiTooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { toast } from "sonner";
import { ArrowDownRight, ArrowUpRight, BriefcaseBusiness, CalendarDays, ChevronDown, CircleArrowDown, CircleArrowUp, Coins, Download, FileSpreadsheet, FileText, Landmark, LayoutDashboard, Loader2, LogOut, Moon, MonitorSmartphone, PanelLeftClose, PanelLeftOpen, Pencil, Plus, ReceiptText, RefreshCw, ShieldCheck, Smartphone, Sun, Target, Trash2, UserRound, Wallet, X, CreditCard as CreditCardIcon } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { useLocation } from "wouter";
import { Area, AreaChart, CartesianGrid, Cell, ComposedChart, Legend, Line, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

type FormState = { id?: number; type: "income" | "expense"; description: string; store: string; product: string; amount: string; category: string; occurredAt: string; icon?: string; paymentMethod?: PaymentMethod; creditCardId?: number; installmentsTotal?: number; buyer?: string; customBuyer?: string };
type InvestmentFormState = { id?: number; institutionDetailIndex?: number; operationOnly?: boolean; ticker: string; category: InvestmentCategory; institution: string; quantity: string; averagePrice: string; currentValue: string; operationType: InvestmentOperationType; operationDate: string; notes: string; contractedRate: string; contractedBenchmark: ContractedBenchmark; benchmarkAnnualRate: string };
type DeleteRequest = { kind: "transaction" | "investment" | "creditCard"; id: number };
const monthNames = ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"];
const defaultYears = Array.from({ length: 11 }, (_, index) => new Date().getFullYear() - index);
const money = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" });
const usdMoney = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });
const chartColors = ["#c084fc", "#22d3ee", "#34d399", "#fbbf24", "#fb7185", "#60a5fa", "#a78bfa"];
const loginLogoUrl = "https://findashlvo-sttsv86x.manus.space/manus-storage/findash-lvo-login-logo_00f5ee0c.png";
function formatInvestmentMoney(item: Pick<LocalInvestment, "category"> & Partial<Pick<LocalInvestment, "fxRate" | "averagePrice">>, value: number) { const isDollarUnitPrice = item.category === "dollar" && Math.abs(value - Number(item.averagePrice)) < 0.0000001; return item.category === "dollar" ? usdMoney.format(isDollarUnitPrice ? value : value / (Number(item.fxRate) || 1)) : money.format(value); }
function quoteTicker(value: string) { return value.trim().toUpperCase().replace(/\.SA$/, ""); }


function initialForm(type: "income" | "expense" = "income"): FormState { return { type, description: "", store: "", product: "", amount: "", category: "", occurredAt: new Date().toISOString().slice(0, 10), icon: type === "income" ? "↗" : "◒", paymentMethod: type === "expense" ? "cash" : undefined, installmentsTotal: 1 }; }
function initialInvestmentForm(): InvestmentFormState { return { ticker: "", category: "fixed-income", institution: "", quantity: "", averagePrice: "", currentValue: "", operationType: "buy", operationDate: new Date().toISOString().slice(0, 10), notes: "", contractedRate: "", contractedBenchmark: "none", benchmarkAnnualRate: "" }; }

export default function Home() {
  const { user, loading, logout } = useAuth();
  const { theme, toggleTheme } = useTheme();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => localStorage.getItem("findash-lvo:sidebar-collapsed") === "true");
  const [location, setLocation] = useLocation();
  const now = new Date();
  const [month, setMonth] = useState(now.getMonth() + 1);
  const [year, setYear] = useState(now.getFullYear());
  const [form, setForm] = useState<FormState | null>(null);
  const [categories, setCategories] = useState<LocalCategory[]>([]);
  const [selectedDate, setSelectedDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [performanceRange, setPerformanceRange] = useState<"week" | "month" | "year">("year");
  const [investmentForm, setInvestmentForm] = useState<InvestmentFormState | null>(null);
  const [investments, setInvestments] = useState<LocalInvestment[]>([]);
  const [creditCards, setCreditCards] = useState<CreditCard[]>([]);
  const [budgets, setBudgets] = useState<MonthlyBudget[]>([]);
  const [refreshingInvestmentTicker, setRefreshingInvestmentTicker] = useState<string | null>(null);
  const [deleteRequest, setDeleteRequest] = useState<DeleteRequest | null>(null);
  const [pendingImport, setPendingImport] = useState<{ transactions: LocalTransaction[]; source: "Excel" | "JSON" } | null>(null);
  const [quickOperation, setQuickOperation] = useState<{ item: LocalInvestment; type: InvestmentOperationType } | null>(null);
  useEffect(() => {
    const budgetCategories = budgetCategoriesForMonth(budgets, `${year}-${String(month).padStart(2, "0")}`);
    if (!budgetCategories.length) return;
    setCategories(current => {
      const known = new Set(current.map(category => category.label.trim().toLocaleLowerCase("pt-BR")));
      const additions = budgetCategories.filter(category => !known.has(category.toLocaleLowerCase("pt-BR"))).map(label => ({ label, icon: "◎" }));
      return additions.length ? [...current, ...additions] : current;
    });
  }, [budgets, month, year]);
  useEffect(() => {
    const startOperation = (event: Event) => {
      const detail = (event as CustomEvent<{ id: number; type: InvestmentOperationType }>).detail;
      const item = investments.find(candidate => candidate.id === detail?.id);
      if (!item) return;
      setQuickOperation({ item, type: detail.type });
    };
    window.addEventListener("findash:investment-operation-start", startOperation as EventListener);
    return () => { window.removeEventListener("findash:investment-operation-start", startOperation as EventListener); };
  }, [investments]);
  useEffect(() => {
    const updateOperation = (event: Event) => {
      const detail = (event as CustomEvent<{ investmentId: number; operation: { id: number; type: InvestmentOperationType; quantity: string; price: string; date: string; institution?: string } }>).detail;
      if (!detail?.operation) return;
      setInvestments(current => current.map(item => item.id === detail.investmentId ? updateInvestmentOperation(item, detail.operation) : item));
    };
    const deleteOperation = (event: Event) => {
      const detail = (event as CustomEvent<{ investmentId: number; operationId: number }>).detail;
      if (!detail?.operationId) return;
      setInvestments(current => current.map(item => item.id === detail.investmentId ? removeInvestmentOperation(item, detail.operationId) : item));
    };
    window.addEventListener("findash:investment-operation-update", updateOperation as EventListener);
    window.addEventListener("findash:investment-operation-delete", deleteOperation as EventListener);
    return () => { window.removeEventListener("findash:investment-operation-update", updateOperation as EventListener); window.removeEventListener("findash:investment-operation-delete", deleteOperation as EventListener); };
  }, []);
  useEffect(() => {
    const updateBudgetDueDay = (event: Event) => {
      const detail = (event as CustomEvent<{ id: number; dueDay: number }>).detail;
      if (!Number.isInteger(detail?.id) || !Number.isInteger(detail?.dueDay) || detail.dueDay < 1 || detail.dueDay > 31) return;
      setBudgets(current => current.map(budget => budget.id === detail.id && budget.kind === "fixed" ? { ...budget, dueDay: detail.dueDay, updatedAt: new Date().toISOString() } : budget));
    };
    window.addEventListener("findash:budget-due-day-update", updateBudgetDueDay as EventListener);
    return () => window.removeEventListener("findash:budget-due-day-update", updateBudgetDueDay as EventListener);
  }, []);
  useEffect(() => {
    const updateBudgetPayment = (event: Event) => {
      const detail = (event as CustomEvent<{ id: number; paid: boolean }>).detail;
      if (!Number.isInteger(detail?.id)) return;
      setBudgets(current => current.map(budget => budget.id === detail.id && budget.kind === "fixed" ? { ...budget, paidAt: detail.paid ? new Date().toISOString() : undefined, updatedAt: new Date().toISOString() } : budget));
    };
    window.addEventListener("findash:budget-payment-update", updateBudgetPayment as EventListener);
    return () => window.removeEventListener("findash:budget-payment-update", updateBudgetPayment as EventListener);
  }, []);
  useEffect(() => {
    const syncBudgetCalendar = () => window.dispatchEvent(new CustomEvent("findash:budget-calendar-sync", { detail: budgets }));
    window.addEventListener("findash:budget-calendar-request", syncBudgetCalendar);
    syncBudgetCalendar();
    return () => window.removeEventListener("findash:budget-calendar-request", syncBudgetCalendar);
  }, [budgets]);
  const quoteItems = useMemo(() => investments.filter(item => quoteTicker(item.ticker) && ["equities", "funds", "treasury", "dollar", "crypto"].includes(item.category)).map(item => ({ ticker: quoteTicker(item.ticker), category: item.category })), [investments]);
  const quoteQuery = trpc.quotes.brapiBatch.useQuery({ items: quoteItems }, { enabled: Boolean(user) && quoteItems.length > 0, staleTime: 5 * 60 * 1000, refetchOnWindowFocus: false });
  const marketWidgetQuery = trpc.quotes.brapiBatch.useQuery({ items: [{ ticker: "USD-BRL", category: "dollar" }, { ticker: "EUR-BRL", category: "dollar" }, { ticker: "BTC", category: "crypto" }, { ticker: "ETH-BRL", category: "crypto" }] }, { enabled: Boolean(user), staleTime: 5 * 60 * 1000, refetchOnWindowFocus: false });
  const benchmarksQuery = trpc.quotes.benchmarks.useQuery(undefined, { enabled: Boolean(user), staleTime: 60 * 60 * 1000, refetchOnWindowFocus: false });
  const allHistoryTicker = "__ALL__";
  const historyOptions = useMemo(() => Array.from(new Set(investments.filter(item => item.ticker.trim()).map(item => item.ticker.trim().toUpperCase()))).sort(), [investments]);
  const [historyTicker, setHistoryTicker] = useState(allHistoryTicker);
  useEffect(() => {
    if (historyTicker !== allHistoryTicker && !historyOptions.includes(historyTicker)) setHistoryTicker(allHistoryTicker);
  }, [historyOptions, historyTicker]);
  const [historyRange, setHistoryRange] = useState<"1mo" | "6mo" | "1y">("1mo");
  const historyAsset = historyTicker === allHistoryTicker ? undefined : investments.find(item => item.ticker.trim().toUpperCase() === historyTicker);
  const historyIsTreasury = historyAsset?.category === "treasury";
  const historyQuery = trpc.quotes.historical.useQuery({ symbol: historyTicker, range: historyRange }, { enabled: Boolean(user && historyTicker && historyTicker !== allHistoryTicker && !historyIsTreasury), staleTime: 15 * 60 * 1000, refetchOnWindowFocus: false });
  const treasuryHistoryQuery = trpc.quotes.treasuryHistorical.useQuery({ symbol: historyTicker, range: historyRange }, { enabled: Boolean(user && historyTicker && historyTicker !== allHistoryTicker && historyIsTreasury), staleTime: 15 * 60 * 1000, refetchOnWindowFocus: false });
  const localHistory = useMemo(() => historyAsset ? investmentPerformanceHistory(historyAsset, historyRange) : [], [historyAsset, historyRange]);
  const unifiedHistory = useMemo(() => {
    if (historyTicker !== allHistoryTicker) return [];
    const points = new Map<number, { close: number; assetEffect: number; fxEffect: number; hasBreakdown: boolean }>();
    investments.filter(item => item.ticker.trim()).forEach(item => investmentPerformanceHistory(item, historyRange).forEach(point => {
      const current = points.get(point.date) ?? { close: 0, assetEffect: 0, fxEffect: 0, hasBreakdown: false };
      current.close += point.close;
      if (Number.isFinite(point.assetEffect)) { current.assetEffect += point.assetEffect as number; current.hasBreakdown = true; }
      if (Number.isFinite(point.fxEffect)) { current.fxEffect += point.fxEffect as number; current.hasBreakdown = true; }
      points.set(point.date, current);
    }));
    return Array.from(points.entries()).sort(([a], [b]) => a - b).map(([date, point]) => ({ date, close: point.close, assetEffect: point.hasBreakdown ? point.assetEffect : undefined, fxEffect: point.hasBreakdown ? point.fxEffect : undefined }));
  }, [historyTicker, historyRange, investments]);
  const remoteHistory = historyIsTreasury ? treasuryHistoryQuery.data ?? [] : historyQuery.data ?? [];
  const effectiveHistory = historyTicker === allHistoryTicker ? unifiedHistory : remoteHistory.length >= 2 ? remoteHistory : localHistory;
  const isTransactions = location === "/lancamentos";
  const isInvestments = location === "/investimentos";
  const isCreditCards = location === "/cartoes";
  const isBudgets = location === "/orcamento";
  const [transactions, setTransactions] = useState<LocalTransaction[]>([]);
  const [logoutOpen, setLogoutOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const sessionsQuery = trpc.sessions.list.useQuery(undefined, { enabled: Boolean(user && profileOpen), retry: 1, refetchOnWindowFocus: false });
  const revokeSession = trpc.sessions.revoke.useMutation({ onSuccess: async () => { await sessionsQuery.refetch(); toast.success("Sessão encerrada remotamente"); }, onError: error => toast.error(error.message || "Não foi possível encerrar esta sessão") });
  const revokeOtherSessions = trpc.sessions.revokeOthers.useMutation({ onSuccess: async () => { await sessionsQuery.refetch(); toast.success("Outras sessões foram encerradas"); }, onError: error => toast.error(error.message || "Não foi possível encerrar as outras sessões") });
  const [paymentFilter, setPaymentFilter] = useState<PaymentMethod | "all">("all");
  const [invoiceMonthMode, setInvoiceMonthMode] = useState<"calendar" | "invoice">("calendar");
  const [cloudHydratedId, setCloudHydratedId] = useState<number | string | null>(null);
  const importInputRef = useRef<HTMLInputElement>(null);
  const userStorageId = user?.id ?? "default";
  const financeStateQuery = trpc.financeState.load.useQuery(undefined, {
    enabled: Boolean(user),
    retry: 1,
    refetchOnWindowFocus: false,
  });
  const financeStateSave = trpc.financeState.save.useMutation({
    onError: error => toast.error(error.message || "Não foi possível sincronizar os dados na nuvem"),
  });

  useEffect(() => {
    if (financeStateQuery.error) toast.error("A nuvem financeira está indisponível. Seus dados atuais foram mantidos nesta sessão.");
  }, [financeStateQuery.error]);

  useEffect(() => {
    if (!user || financeStateQuery.isLoading || financeStateQuery.isFetching || financeStateQuery.error || cloudHydratedId === userStorageId) return;
    const remote = financeStateQuery.data?.payload;
    if (remote) {
      const remoteBudgets = Array.isArray(remote.budgets) ? remote.budgets as MonthlyBudget[] : [];
      const recoveredBudgets = recoverLocalBudgets(remoteBudgets, loadLocalBudgets(userStorageId));
      setTransactions(Array.isArray(remote.transactions) ? remote.transactions as LocalTransaction[] : []);
      setInvestments(Array.isArray(remote.investments) ? remote.investments as LocalInvestment[] : []);
      setCreditCards(Array.isArray(remote.creditCards) ? remote.creditCards as CreditCard[] : []);
      setCategories(Array.isArray(remote.categories) ? remote.categories as LocalCategory[] : []);
      setBudgets(recoveredBudgets);
      if (!remoteBudgets.length && recoveredBudgets.length) toast.success("Orçamentos locais recuperados e prontos para sincronizar");
    } else {
      const localPayload = {
        version: 1 as const,
        transactions: loadLocalTransactions(userStorageId),
        investments: loadLocalInvestments(userStorageId),
        creditCards: loadLocalCreditCards(userStorageId),
        categories: loadLocalCategories(userStorageId),
        budgets: loadLocalBudgets(userStorageId),
      };
      setTransactions(localPayload.transactions);
      setInvestments(localPayload.investments);
      setCreditCards(localPayload.creditCards);
      setCategories(localPayload.categories);
      setBudgets(localPayload.budgets);
      if (localPayload.transactions.length || localPayload.investments.length || localPayload.creditCards.length || localPayload.categories.length || localPayload.budgets.length) {
        financeStateSave.mutate({ payload: localPayload });
      }
    }
    setCloudHydratedId(userStorageId);
  }, [financeStateQuery.data, financeStateQuery.error, financeStateQuery.isFetching, financeStateQuery.isLoading, cloudHydratedId, user, userStorageId]);

  useEffect(() => {
    if (!user || cloudHydratedId !== userStorageId) return;
    const historyInvestments = recordDailyInvestmentHistory(investments);
    const timer = window.setTimeout(() => financeStateSave.mutate({
      payload: { version: 1, transactions, investments: historyInvestments, creditCards, categories, budgets },
    }), 700);
    return () => window.clearTimeout(timer);
  }, [transactions, investments, creditCards, categories, budgets, user, userStorageId, cloudHydratedId]);

  useEffect(() => {
    if (!user || cloudHydratedId !== userStorageId) return;
    saveLocalBudgets(userStorageId, budgets);
  }, [budgets, user, userStorageId, cloudHydratedId]);

  useEffect(() => {
    const data = benchmarksQuery.data;
    if (!data) return;
    setInvestments(current => {
      let changed = false;
      const next = current.map(item => {
        if (item.contractedBenchmark !== "CDI" && item.contractedBenchmark !== "IPCA+") return item;
        const benchmarkAnnualRate = String((item.contractedBenchmark === "CDI" ? data.cdiAnnualRate : data.ipcaAnnualRate).toFixed(2));
        const details = item.institutionDetails?.map(detail => {
          const detailItem = { ...item, quantity: detail.quantity, averagePrice: detail.averagePrice, currentValue: detail.currentValue, contractedRate: detail.contractedRate ?? item.contractedRate, contractedBenchmark: detail.contractedBenchmark ?? item.contractedBenchmark, benchmarkAnnualRate };
          const currentValue = String(investmentAccruedValue(detailItem));
          return { ...detail, benchmarkAnnualRate, currentValue, profit: String(Number(currentValue) - (Number(detail.costBasis) || Number(detail.quantity) * Number(detail.averagePrice))), profitabilityPercent: Number(detail.costBasis) > 0 ? String(((Number(currentValue) - Number(detail.costBasis)) / Number(detail.costBasis)) * 100) : detail.profitabilityPercent };
        });
        const currentValue = item.marketPrice?.trim() ? item.currentValue : String(investmentAccruedValue({ ...item, benchmarkAnnualRate }));
        if (item.benchmarkAnnualRate === benchmarkAnnualRate && item.currentValue === currentValue && JSON.stringify(item.institutionDetails) === JSON.stringify(details)) return item;
        changed = true;
        return { ...item, benchmarkAnnualRate, currentValue, institutionDetails: details };
      });
      return changed ? next : current;
    });
  }, [benchmarksQuery.data]);

  useEffect(() => {
    if (!quoteQuery.data?.length) return;
    setInvestments(current => {
      let changed = false;
      const next = current.map(item => {
        const quote = quoteQuery.data.find(result => quoteTicker(result.ticker) === quoteTicker(item.ticker));
        if (!quote) return item;
        const usdQuote = marketWidgetQuery.data?.find(result => result.ok && ["USD-BRL", "USDBRL"].includes(result.ticker.toUpperCase()));
        const usdBrl = item.category === "dollar" ? (usdQuote?.ok ? Number(usdQuote.price) : Number.NaN) : 1;
        const nextItemBase = applyInvestmentQuote(item, quote, usdBrl);
        const nextItem = item.category === "dollar" && Number.isFinite(usdBrl) && usdBrl > 0 ? { ...nextItemBase, fxRate: String(usdBrl), currentValue: String(Number(item.quantity || 0) * Number(nextItemBase.marketPrice || 0) * usdBrl) } : nextItemBase;
        if (nextItem.marketPrice === item.marketPrice && nextItem.currentValue === item.currentValue && nextItem.quoteChangePercent === item.quoteChangePercent && nextItem.quoteFetchedAt === item.quoteFetchedAt && nextItem.quoteSource === item.quoteSource && nextItem.quoteError === item.quoteError) return item;
        changed = true;
        return nextItem;
      });
      return changed ? next : current;
    });
  }, [quoteQuery.data, marketWidgetQuery.data]);

  useEffect(() => {
    setSelectedDate(`${year}-${String(month).padStart(2, "0")}-01`);
  }, [month, year]);

  useEffect(() => {
    const fixedIncomeModal = investmentForm?.category === "fixed-income";
    document.querySelectorAll<HTMLElement>("label").forEach(label => {
      const field = label.parentElement;
      if (!field) return;
      if (label.textContent === "Quantidade") {
        field.style.display = fixedIncomeModal ? "none" : "";
      }
      if (label.textContent === "Preço da operação / PM" || label.dataset.fixedIncomeLabel === "true") {
        label.dataset.fixedIncomeLabel = "true";
        label.textContent = fixedIncomeModal ? "Valor aplicado" : "Preço da operação / PM";
      }
    });
    document.querySelectorAll<HTMLElement>("article").forEach(card => {
      if (!card.textContent?.includes("Renda fixa")) return;
      const valueLine = Array.from(card.querySelectorAll("p")).find(line => line.textContent?.startsWith("Quantidade:"));
      if (!valueLine) return;
      const fixedItem = investments.find(item => card.textContent?.includes(item.ticker) && item.category === "fixed-income");
      if (fixedItem) valueLine.textContent = `Valor aplicado: ${money.format(investmentCost(fixedItem))}`;
    });
  }, [investmentForm?.category, investments]);

  const saving = false;
  const refreshQuotes = async (targetTicker?: string) => {
    if (targetTicker) setRefreshingInvestmentTicker(targetTicker.toUpperCase());
    try {
      const result = await quoteQuery.refetch();
      const failures = (result.data ?? []).filter(item => !item.ok);
      if (failures.length) toast.error(`Não foi possível atualizar ${failures.length} cotação(ões)`);
      else toast.success("Cotações atualizadas com sucesso");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Não foi possível atualizar as cotações");
    } finally {
      setRefreshingInvestmentTicker(null);
    }
  };
  useEffect(() => { localStorage.setItem("findash-lvo:sidebar-collapsed", String(sidebarCollapsed)); }, [sidebarCollapsed]);
  const visibleTransactions = useMemo(() => {
    const periodTransactions = invoiceMonthMode === "invoice" ? filterLocalTransactionsByInvoiceMonth(transactions, month, year) : filterLocalTransactions(transactions, month, year);
    return sortTransactionsByDate(paymentFilter === "all" ? periodTransactions : periodTransactions.filter(item => item.paymentMethod === paymentFilter));
  }, [transactions, month, year, paymentFilter, invoiceMonthMode]);
  const summary = useMemo(() => visibleTransactions.reduce((acc, item) => { const value = Number(item.amount); if (item.type === "income") acc.income += value; else { acc.expense += value; if (isInvestmentExpense(item)) acc.investmentExpense += value; } return acc; }, { income: 0, expense: 0, investmentExpense: 0, expenseWithoutInvestments: 0 }), [visibleTransactions]);
  summary.expenseWithoutInvestments = summary.expense - summary.investmentExpense;
  const yearOptions = useMemo(() => Array.from(new Set([...defaultYears, ...transactions.map(item => new Date(item.occurredAt).getFullYear())])).sort((a, b) => b - a), [transactions]);

  if (loading) return <div className="min-h-screen grid place-items-center"><div className="animate-pulse text-muted-foreground">Carregando seu espaço financeiro...</div></div>;
  if (!user) return <Landing onLogin={startLogin} />;

  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    if (!form || !user) return;
    const amount = Number(form.amount);
    const derivedDescription = form.type === "income" ? form.store.trim() : form.product.trim() || form.store.trim() || form.description.trim();
    if (!derivedDescription || !form.category.trim() || !Number.isFinite(amount) || amount <= 0) {
      toast.error(`Preencha ${form.type === "income" ? "fonte pagadora" : "loja ou produto"}, valor e categoria`);
      return;
    }
    const paymentMethod = form.type === "expense" ? (form.paymentMethod ?? "cash") : undefined;
    const installmentsTotal = paymentMethod === "credit" ? Math.max(1, Math.floor(Number(form.installmentsTotal || 1))) : undefined;
    const selectedCard = form.creditCardId ? creditCards.find(card => card.id === form.creditCardId) : undefined;
    const resolvedBuyer = form.buyer === "OUTRO" ? form.customBuyer?.trim() : form.buyer?.trim();
    if (paymentMethod === "credit" && (!selectedCard || (selectedCard.cardType === "shared" && !resolvedBuyer))) {
      toast.error(selectedCard?.cardType === "shared" ? "Informe quem realizou a compra" : "Escolha um cartão para a compra no crédito");
      return;
    }
    const previousTransaction = form.id ? transactions.find(item => item.id === form.id) : undefined;
    const purchaseId = previousTransaction?.purchaseId ?? Date.now();
    const nowIso = new Date().toISOString();
    if (form.id) {
      setTransactions(current => current.map(item => item.id === form.id ? {
        ...item,
        type: form.type,
        description: derivedDescription,
        store: form.store.trim(),
        product: form.product.trim(),
        amount: amount.toFixed(2),
        category: form.category.trim(),
        icon: form.icon,
        occurredAt: new Date(`${form.occurredAt}T12:00:00`).toISOString(),
        paymentMethod,
        creditCardId: form.creditCardId,
        installmentsTotal,
        invoiceMonth: paymentMethod === "credit" && selectedCard ? creditCardPurchaseInvoiceMonth(selectedCard, form.occurredAt) : undefined,
        updatedAt: nowIso,
      } : item));
      if (previousTransaction?.paymentMethod === "credit" && previousTransaction.purchaseId) {
        setCreditCards(current => removeCreditPurchase(current, previousTransaction.purchaseId!));
      }
      if (paymentMethod === "credit" && form.creditCardId) {
        setCreditCards(current => applyCreditPurchase(current, { cardId: form.creditCardId!, purchaseId, description: derivedDescription, store: form.store.trim(), product: form.product.trim(), category: form.category.trim(), buyer: resolvedBuyer, total: amount, purchasedAt: form.occurredAt, installments: installmentsTotal || 1 }));
      }
      toast.success("Lançamento atualizado");
    } else {
      setTransactions(current => createLocalTransaction(current, {
        userId: Number(user.id),
        type: form.type,
        description: derivedDescription,
        store: form.store.trim(),
        product: form.product.trim(),
        amount: paymentMethod === "credit" ? (amount / (installmentsTotal || 1)).toFixed(2) : amount.toFixed(2),
        category: form.category.trim(),
        icon: form.icon,
        occurredAt: new Date(`${form.occurredAt}T12:00:00`).toISOString(),
        paymentMethod,
        creditCardId: form.creditCardId,
        creditTotal: paymentMethod === "credit" ? amount.toFixed(2) : undefined,
        installmentIndex: paymentMethod === "credit" ? 1 : undefined,
        installmentsTotal,
        purchaseId: paymentMethod === "credit" ? purchaseId : undefined,
        invoiceMonth: paymentMethod === "credit" && selectedCard ? creditCardPurchaseInvoiceMonth(selectedCard, form.occurredAt) : undefined,
      }));
      if (paymentMethod === "credit" && form.creditCardId) {
        setCreditCards(current => applyCreditPurchase(current, { cardId: form.creditCardId!, purchaseId, description: derivedDescription, store: form.store.trim(), product: form.product.trim(), category: form.category.trim(), buyer: resolvedBuyer, total: amount, purchasedAt: form.occurredAt, installments: installmentsTotal || 1 }));
      }
      toast.success(paymentMethod === "credit" ? "Compra parcelada adicionada à fatura" : "Lançamento adicionado");
    }
    setForm(null);
  };
  const remove = (id: number) => {
    const removed = transactions.find(item => item.id === id);
    setTransactions(current => current.filter(item => item.id !== id));
    if (removed?.paymentMethod === "credit" && removed.purchaseId) setCreditCards(current => removeCreditPurchase(current, removed.purchaseId!));
    toast.success("Lançamento excluído");
  };
  const confirmDelete = () => {
    if (!deleteRequest) return;
    if (deleteRequest.kind === "transaction") remove(deleteRequest.id);
    if (deleteRequest.kind === "investment") setInvestments(current => current.filter(item => item.id !== deleteRequest.id));
    if (deleteRequest.kind === "creditCard") setCreditCards(current => deleteLocalCreditCard(current, deleteRequest.id));
    if (deleteRequest.kind !== "transaction") toast.success(deleteRequest.kind === "investment" ? "Investimento excluído" : "Cartão excluído");
    setDeleteRequest(null);
  };
  const downloadBackup = () => {
    const backup = createFullBackup({ transactions, investments, creditCards, categories, budgets });
    const blob = new Blob([JSON.stringify(backup, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `findash-lvo-backup-${new Date().toISOString().slice(0, 10)}.json`;
    anchor.click();
    URL.revokeObjectURL(url);
    toast.success("Backup completo exportado");
  };
  const importBackup = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    try {
      const isExcel = /\.(xlsx|xls)$/i.test(file.name) || ["application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", "application/vnd.ms-excel"].includes(file.type);
      if (!isExcel) {
        const source = await file.text();
        const fullBackup = parseFullBackup(source);
        if (fullBackup) {
          if (!window.confirm("Restaurar o backup completo? Os dados atuais deste dispositivo serão substituídos.")) return;
          setTransactions(fullBackup.transactions);
          setInvestments(fullBackup.investments);
          setCreditCards(fullBackup.creditCards);
          setCategories(fullBackup.categories);
          setBudgets(fullBackup.budgets);
          toast.success("Backup completo restaurado e pronto para sincronizar");
          return;
        }
        const imported = parseBackupJson(source).map((item, index) => ({ ...item, id: index + 1, userId: Number(user?.id ?? 1) }));
        setPendingImport({ transactions: imported, source: "JSON" });
        return;
      }
      const imported = parseExcelTransactions(await file.arrayBuffer(), Number(user?.id ?? 1));
      setPendingImport({ transactions: imported, source: isExcel ? "Excel" : "JSON" });
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Não foi possível importar o backup");
    }
  };
  const exportExcel = async () => {
    try {
      const { exportFinancialWorkbook } = await import("@/lib/financialExports");
      exportFinancialWorkbook({ transactions, investments, creditCards, income: summary.income, expense: summary.expense });
      toast.success("Planilha Excel exportada");
    } catch {
      toast.error("Não foi possível gerar a planilha Excel");
    }
  };
  const exportPdf = async () => {
    try {
      const { exportFinancialPdf } = await import("@/lib/financialExports");
      const performance = buildPerformanceData(transactions, year, month, performanceRange, selectedDate);
      exportFinancialPdf({ transactions, investments, creditCards, income: summary.income, expense: summary.expense, performance });
      toast.success("Relatório PDF exportado");
    } catch {
      toast.error("Não foi possível gerar o relatório PDF");
    }
  };
  const grouped = { income: visibleTransactions.filter(t => t.type === "income"), expense: visibleTransactions.filter(t => t.type === "expense") };
  const saveCreditCard = (form: CreditCardForm) => {
    const nowIso = new Date().toISOString();
    if (form.id) { const { id: _id, ...cardPatch } = form; setCreditCards(current => updateLocalCreditCard(current, form.id!, cardPatch, new Date(nowIso))); }
    else setCreditCards(current => createLocalCreditCard(current, { ...form, userId: Number(user.id) }));
  };
  const confirmLogout = async () => {
    recordAuthEvent("logout_requested");
    try {
      await logout();
      recordAuthEvent("logout_succeeded");
      toast.success("Sessão encerrada");
    } catch (error) {
      recordAuthEvent("logout_failed", { message: error instanceof Error ? error.message : "unknown" });
      toast.error("Não foi possível encerrar a sessão");
    } finally {
      setLogoutOpen(false);
    }
  };
  const toggleCreditCardPaid = (id: number, invoiceMonth = new Date().toISOString().slice(0, 7)) => setCreditCards(current => {
    const card = current.find(item => item.id === id);
    if (!card) return current;
    const currentPaid = card.paidInvoices?.[invoiceMonth] ?? (invoiceMonth === card.invoiceMonth ? card.isPaid : false);
    return setCreditCardInvoicePaid(current, id, invoiceMonth, !currentPaid);
  });

  return <div className="app-shell min-h-screen text-foreground">
    <aside className={`glass-sidebar fixed inset-y-0 left-0 z-50 hidden border-r py-6 lg:flex lg:flex-col transition-[width,padding] duration-300 ease-out ${sidebarCollapsed ? "w-20 px-2" : "w-64 px-5"}`}>
      <div className={`flex items-center px-2 ${sidebarCollapsed ? "justify-center gap-1" : "gap-3"}`}><Avatar className={`h-10 w-10 shrink-0 rounded-2xl shadow-lg shadow-primary/20 ${sidebarCollapsed ? "h-9 w-9" : ""}`}><AvatarImage src={user.avatarUrl ?? undefined} alt={user.name ?? "Avatar do usuário"} /><AvatarFallback>LO</AvatarFallback></Avatar>{!sidebarCollapsed && <div><p className="font-semibold tracking-tight">Findash LVO</p><p className="text-xs text-muted-foreground">Seu dinheiro, claro.</p></div>}<button type="button" onClick={() => setSidebarCollapsed(value => !value)} className={`${sidebarCollapsed ? "h-9 w-9 shrink-0 p-1" : "ml-auto p-1.5"} rounded-lg border border-white/10 text-muted-foreground transition hover:border-primary/40 hover:text-foreground`} aria-label={sidebarCollapsed ? "Expandir menu lateral" : "Recolher menu lateral"}>{sidebarCollapsed ? <PanelLeftOpen className="h-4 w-4" /> : <PanelLeftClose className="h-4 w-4" />}</button></div>
      <nav className="mt-12 space-y-2"><NavItem collapsed={sidebarCollapsed} icon={LayoutDashboard} label="Visão geral" active={!isTransactions && !isInvestments && !isCreditCards && !isBudgets} onClick={() => setLocation("/")} /><NavItem collapsed={sidebarCollapsed} icon={ReceiptText} label="Lançamentos" active={isTransactions} onClick={() => setLocation("/lancamentos")} /><NavItem collapsed={sidebarCollapsed} icon={Target} label="Orçamento" active={isBudgets} onClick={() => setLocation("/orcamento")} /><NavItem collapsed={sidebarCollapsed} icon={BriefcaseBusiness} label="Investimentos" active={isInvestments} onClick={() => setLocation("/investimentos")} /><NavItem collapsed={sidebarCollapsed} icon={CreditCardIcon} label="Cartões" active={isCreditCards} onClick={() => setLocation("/cartoes")} /></nav>
      <div className={`mt-auto rounded-2xl border border-white/8 bg-white/[0.03] p-3 ${sidebarCollapsed ? "px-2" : ""}`}><button type="button" className={`flex w-full items-center rounded-xl text-left transition hover:bg-white/5 ${sidebarCollapsed ? "justify-center p-1" : "gap-3 p-1"}`} onClick={() => setProfileOpen(true)} title="Abrir perfil" aria-label="Abrir perfil"><Avatar className="h-9 w-9 shrink-0"><AvatarImage src={user.avatarUrl ?? undefined} alt={user.name ?? "Avatar do usuário"} /><AvatarFallback>LO</AvatarFallback></Avatar>{!sidebarCollapsed && <div className="min-w-0"><p className="truncate text-sm font-medium">{user.name ?? "Usuário"}</p><p className="truncate text-xs text-muted-foreground">{user.email}</p></div>}</button><Button variant="ghost" size="sm" className={`mt-3 min-h-10 w-full text-muted-foreground ${sidebarCollapsed ? "justify-center px-0" : "justify-start"}`} disabled={loading} onClick={() => setLogoutOpen(true)} title={sidebarCollapsed ? "Sair" : undefined} aria-label="Sair"><LogOut className={`${sidebarCollapsed ? "" : "mr-2"} h-4 w-4`} />{!sidebarCollapsed && "Sair"}</Button></div>
    </aside>
    <main className={`transition-[padding] duration-300 ease-out ${sidebarCollapsed ? "lg:pl-20" : "lg:pl-64"}`}><header className="glass-header sticky top-0 z-20 border-b px-4 py-4 backdrop-blur-xl sm:px-8"><div className="mx-auto flex max-w-7xl items-center justify-between"><div><p className="text-xs font-medium uppercase tracking-[0.2em] text-primary">{isTransactions ? "Controle" : isInvestments ? "Patrimônio" : isCreditCards ? "Pagamentos" : isBudgets ? "Planejamento" : "Resumo financeiro"}</p><h1 className="mt-1 text-xl font-semibold tracking-tight sm:text-2xl">{isTransactions ? "Seus lançamentos" : isInvestments ? "Sua carteira de investimentos" : isCreditCards ? "Seus cartões de crédito" : isBudgets ? "Seu orçamento mensal" : `Olá, ${user.name?.split(" ")[0] ?? "bem-vindo"}.`}</h1></div><div className="flex items-center gap-2"><div className="hidden items-center gap-2 rounded-xl border border-white/8 bg-white/[0.03] px-3 py-2 sm:flex"><CalendarDays className="h-4 w-4 text-muted-foreground" /><select className="bg-transparent text-sm outline-none" value={month} onChange={e => setMonth(Number(e.target.value))}>{monthNames.map((m, i) => <option className="bg-[#10131b]" key={m} value={i + 1}>{m}</option>)}</select><select className="bg-transparent text-sm outline-none" value={year} onChange={e => setYear(Number(e.target.value))}>{yearOptions.map(option => <option className="bg-[#10131b]" key={option} value={option}>{option}</option>)}</select></div><div className="hidden items-center gap-1 md:flex"><Button variant="outline" size="sm" className="rounded-xl border-white/15 bg-white/[0.03]" onClick={() => importInputRef.current?.click()} title="Importar lançamentos em JSON ou Excel"><Download className="mr-1.5 h-4 w-4 rotate-180" />Importar</Button><ExportMenu onJson={downloadBackup} onExcel={exportExcel} onPdf={exportPdf} /></div><input ref={importInputRef} type="file" accept="application/json,.json,.xlsx,.xls,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel" className="hidden" onChange={importBackup} /><Button variant="outline" size="icon" className="rounded-xl border-white/15 bg-white/[0.03]" onClick={toggleTheme} title={theme === "dark" ? "Ativar light mode" : "Ativar dark mode"}>{theme === "dark" ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}</Button><Button size="icon" className="rounded-xl" onClick={() => setForm(initialForm())}><Plus className="h-5 w-5" /></Button></div></div></header>
      <div className="mx-auto max-w-7xl space-y-6 p-4 sm:p-8"><div className="grid grid-cols-2 gap-2 sm:hidden"><Button className="w-full px-2 text-xs" variant={!isTransactions && !isInvestments && !isCreditCards && !isBudgets ? "secondary" : "ghost"} onClick={() => setLocation("/")}><LayoutDashboard className="mr-1.5 h-4 w-4 shrink-0" />Resumo</Button><Button className="w-full px-2 text-xs" variant={isTransactions ? "secondary" : "ghost"} onClick={() => setLocation("/lancamentos")}><ReceiptText className="mr-1.5 h-4 w-4 shrink-0" />Lançamentos</Button><Button className="w-full px-2 text-xs" variant={isBudgets ? "secondary" : "ghost"} onClick={() => setLocation("/orcamento")}><Target className="mr-1.5 h-4 w-4 shrink-0" />Orçamento</Button><Button className="w-full px-2 text-xs" variant={isInvestments ? "secondary" : "ghost"} onClick={() => setLocation("/investimentos")}><BriefcaseBusiness className="mr-1.5 h-4 w-4 shrink-0" />Investimentos</Button><Button className="w-full px-2 text-xs" variant={isCreditCards ? "secondary" : "ghost"} onClick={() => setLocation("/cartoes")}><CreditCardIcon className="mr-1.5 h-4 w-4 shrink-0" />Cartões</Button></div><div className="flex items-center gap-2 rounded-2xl border border-white/8 bg-white/[0.03] p-3 sm:hidden"><CalendarDays className="h-4 w-4 text-muted-foreground" /><select className="flex-1 bg-transparent text-sm outline-none" value={month} onChange={e => setMonth(Number(e.target.value))}>{monthNames.map((m, i) => <option className="bg-[#10131b]" key={m} value={i + 1}>{m}</option>)}</select><span className="text-muted-foreground">/</span><select className="bg-transparent text-sm outline-none" value={year} onChange={e => setYear(Number(e.target.value))}>{yearOptions.map(option => <option className="bg-[#10131b]" key={option} value={option}>{option}</option>)}</select></div><div className="flex flex-wrap gap-2 md:hidden"><Button variant="outline" size="sm" className="border-white/15 bg-white/[0.03]" onClick={() => importInputRef.current?.click()}><Download className="mr-1.5 h-4 w-4 rotate-180" />Importar</Button><ExportMenu compact onJson={downloadBackup} onExcel={exportExcel} onPdf={exportPdf} /><Button variant="outline" size="icon" className="border-white/15 bg-white/[0.03]" onClick={toggleTheme} title={theme === "dark" ? "Ativar light mode" : "Ativar dark mode"}>{theme === "dark" ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}</Button></div><div className="flex items-center gap-3 rounded-2xl border border-white/10 bg-white/[0.03] p-3 md:hidden"><button type="button" className="flex min-w-0 flex-1 items-center gap-3 rounded-xl p-1 text-left hover:bg-white/5" onClick={() => setProfileOpen(true)}><Avatar className="h-9 w-9 shrink-0"><AvatarImage src={user.avatarUrl ?? undefined} alt={user.name ?? "Avatar do usuário"} /><AvatarFallback>LO</AvatarFallback></Avatar><span className="min-w-0"><span className="block truncate text-sm font-medium">{user.name ?? "Usuário"}</span><span className="block truncate text-xs text-muted-foreground">Abrir perfil e dispositivos</span></span></button><Button variant="ghost" size="sm" className="min-h-10 shrink-0 text-muted-foreground" disabled={loading} onClick={() => setLogoutOpen(true)} aria-label="Sair"><LogOut className="mr-2 h-4 w-4" />Sair</Button></div>{isTransactions ? <TransactionsPage grouped={grouped} invoiceMonthMode={invoiceMonthMode} onInvoiceMonthModeChange={setInvoiceMonthMode} onEdit={(item: any) => setForm({ id: item.id, type: item.type, description: item.description, store: item.store ?? "", product: item.product ?? "", amount: String(item.creditTotal ?? item.amount), category: item.category, icon: item.icon, occurredAt: new Date(item.occurredAt).toISOString().slice(0, 10), paymentMethod: item.paymentMethod, creditCardId: item.creditCardId, installmentsTotal: item.installmentsTotal ?? 1, buyer: ["LEONARDO", "LEANDRO", "FERLANE", "JOANA", "504", "OUTRO"].includes(item.buyer ?? "") ? item.buyer : item.buyer ? "OUTRO" : "", customBuyer: item.buyer && !["LEONARDO", "LEANDRO", "FERLANE", "JOANA", "504", "OUTRO"].includes(item.buyer) ? item.buyer : "" })} onDelete={(id: number) => setDeleteRequest({ kind: "transaction", id })} /> : isBudgets ? <BudgetPage budgets={budgets} transactions={transactions} month={`${year}-${String(month).padStart(2, "0")}`} onMonthChange={value => { const [selectedYear, selectedMonth] = value.split("-").map(Number); setYear(selectedYear); setMonth(selectedMonth); }} onSave={(draft: BudgetDraft) => { if (!draft.category.trim() || !Number.isFinite(Number(draft.plannedAmount)) || Number(draft.plannedAmount) < 0) { toast.error("Informe categoria e limite mensal válidos"); return; } const budgetMonth = `${year}-${String(month).padStart(2, "0")}`; setBudgets(current => draft.id ? updateMonthlyBudget(current, draft.id, draft) : createMonthlyBudget(current, { month: budgetMonth, category: draft.category, kind: draft.kind, plannedAmount: draft.plannedAmount, notes: draft.notes })); toast.success(draft.id ? "Orçamento atualizado" : "Categoria adicionada ao orçamento"); }} onRemove={id => { setBudgets(current => removeMonthlyBudget(current, id)); toast.success("Categoria removida do orçamento"); }} onCopyPrevious={() => { setBudgets(current => copyPreviousMonthBudget(current, `${year}-${String(month).padStart(2, "0")}`)); toast.success("Categorias do mês anterior copiadas"); }} /> : isInvestments ? <InvestmentsPage benchmarks={benchmarksQuery.data} investments={investments} onAdd={() => setInvestmentForm(initialInvestmentForm())} onRefreshQuotes={refreshQuotes} quotesLoading={quoteQuery.isFetching} refreshingInvestmentTicker={refreshingInvestmentTicker} onEdit={(item: LocalInvestment) => setInvestmentForm({ id: item.id, ticker: item.ticker, category: item.category, institution: item.institution, quantity: item.quantity, averagePrice: item.averagePrice, currentValue: item.currentValue, operationType: "buy", operationDate: new Date().toISOString().slice(0, 10), notes: item.notes, contractedRate: item.contractedRate ?? "", contractedBenchmark: item.contractedBenchmark ?? "none", benchmarkAnnualRate: item.benchmarkAnnualRate ?? "" })} onEditInstitution={(item: LocalInvestment, detail: any, index: number) => setInvestmentForm({ id: item.id, institutionDetailIndex: index, ticker: item.ticker, category: item.category, institution: detail.institution, quantity: detail.quantity, averagePrice: detail.averagePrice, currentValue: detail.currentValue, operationType: "buy", operationDate: new Date().toISOString().slice(0, 10), notes: item.notes, contractedRate: detail.contractedRate ?? item.contractedRate ?? "", contractedBenchmark: detail.contractedBenchmark ?? item.contractedBenchmark ?? "none", benchmarkAnnualRate: detail.benchmarkAnnualRate ?? item.benchmarkAnnualRate ?? "" })} onDelete={(id: number) => setDeleteRequest({ kind: "investment", id })} historyTicker={historyTicker} historyOptions={[allHistoryTicker, ...historyOptions]} onHistoryTickerChange={setHistoryTicker} historyData={effectiveHistory} historyLoading={historyTicker === allHistoryTicker ? false : historyIsTreasury ? treasuryHistoryQuery.isFetching : historyQuery.isFetching} historyRange={historyRange} onHistoryRangeChange={setHistoryRange} historyError={historyTicker === allHistoryTicker ? undefined : historyIsTreasury ? treasuryHistoryQuery.error?.message : historyQuery.error?.message} /> : isCreditCards ? <CreditCardsPage cards={creditCards} onSave={saveCreditCard} onDelete={(id: number) => setDeleteRequest({ kind: "creditCard", id })} onTogglePaid={toggleCreditCardPaid} /> : <Dashboard summary={summary} transactions={visibleTransactions} allTransactions={transactions} month={month} year={year} selectedDate={selectedDate} paymentFilter={paymentFilter} onPaymentFilterChange={setPaymentFilter} performanceRange={performanceRange} onPerformanceRange={setPerformanceRange} onSelectDate={setSelectedDate} onAdd={() => setForm(initialForm())} investments={investments} onAddInvestment={() => setInvestmentForm(initialInvestmentForm())} onRefreshQuotes={refreshQuotes} quotesLoading={quoteQuery.isFetching} creditCards={creditCards} onToggleCreditCardPaid={toggleCreditCardPaid} onAddCreditCard={() => setLocation("/cartoes")} marketWidgetQuotes={marketWidgetQuery.data ?? []} />}</div>
    </main>
    {quickOperation && <QuickOperationDialog key={`${quickOperation.item.id}-${quickOperation.type}`} item={quickOperation.item} type={quickOperation.type} onClose={() => setQuickOperation(null)} onSubmit={(operation) => { if (operation.type === "sell" && Number(operation.quantity) > Number(quickOperation.item.quantity)) { toast.error("O resgate não pode exceder a quantidade disponível"); return; } setInvestments(current => current.map(item => item.id === quickOperation.item.id ? appendInvestmentOperation(item, operation) : item)); toast.success(operation.type === "buy" ? "Aplicação registrada" : "Resgate registrado"); setQuickOperation(null); }} />}
    <AlertDialog open={Boolean(deleteRequest)} onOpenChange={open => { if (!open) setDeleteRequest(null); }}><AlertDialogContent className="glass-modal max-w-md border-white/15"><AlertDialogHeader><AlertDialogTitle>Confirmar exclusão?</AlertDialogTitle><AlertDialogDescription>Esta ação remove permanentemente o registro financeiro selecionado deste navegador.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Cancelar</AlertDialogCancel><AlertDialogAction className="bg-rose-500 text-white hover:bg-rose-600" onClick={event => { event.preventDefault(); confirmDelete(); }}>Excluir</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <AlertDialog open={logoutOpen} onOpenChange={setLogoutOpen}><AlertDialogContent className="glass-modal max-w-md border-white/15"><AlertDialogHeader><AlertDialogTitle>Encerrar sessão?</AlertDialogTitle><AlertDialogDescription>Você será desconectado deste dispositivo. Seus dados locais permanecerão disponíveis neste navegador.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={loading}>Cancelar</AlertDialogCancel><AlertDialogAction disabled={loading} onClick={event => { event.preventDefault(); void confirmLogout(); }}>{loading ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Encerrando...</> : "Sair da conta"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <AlertDialog open={Boolean(pendingImport)} onOpenChange={open => { if (!open) setPendingImport(null); }}><AlertDialogContent className="glass-modal max-w-md border-white/15"><AlertDialogHeader><AlertDialogTitle>Substituir lançamentos atuais?</AlertDialogTitle><AlertDialogDescription>{pendingImport ? `Foram encontrados ${pendingImport.transactions.length} lançamento(s) no arquivo ${pendingImport.source}. Ao confirmar, a lista atual de lançamentos será substituída por esses dados.` : ""}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Cancelar</AlertDialogCancel><AlertDialogAction onClick={event => { event.preventDefault(); if (!pendingImport) return; setTransactions(pendingImport.transactions); toast.success(`${pendingImport.transactions.length} lançamento(s) importado(s) do ${pendingImport.source}`); setPendingImport(null); }}>Confirmar importação</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <ProfileDialog open={profileOpen} onOpenChange={setProfileOpen} user={user} sessionsQuery={sessionsQuery} revokeSession={revokeSession} revokeOtherSessions={revokeOtherSessions} onBackupExport={downloadBackup} onBackupImport={importBackup} />
    {form && <TransactionModal form={form} setForm={setForm} categories={categories} onAddCategory={(category: LocalCategory) => setCategories(current => addLocalCategory(current, category))} onEditCategory={(label: string, category: LocalCategory) => setCategories(current => updateLocalCategory(current, label, category))} onDeleteCategory={(label: string) => { if (!isDefaultCategory(label)) setCategories(current => deleteLocalCategory(current, label)); }} creditCards={creditCards} invoicePreview={form.paymentMethod === "credit" && form.creditCardId ? (() => { const card = creditCards.find(item => item.id === form.creditCardId); return card ? { cardName: card.name, invoiceMonth: creditCardPurchaseInvoiceMonth(card, form.occurredAt), closingDay: card.closingDay } : undefined; })() : undefined} onSubmit={submit} saving={saving} onClose={() => setForm(null)} />}
    {investmentForm && <InvestmentModal benchmarks={benchmarksQuery.data} form={investmentForm} setForm={setInvestmentForm} onClose={() => setInvestmentForm(null)} onSubmit={(event: React.FormEvent) => { event.preventDefault(); const quantity = investmentForm.category === "fixed-income" ? 1 : Number(investmentForm.quantity || 0); const averagePrice = Number(investmentForm.averagePrice || 0); if (!investmentForm.ticker.trim() || !Number.isFinite(quantity) || quantity <= 0 || !Number.isFinite(averagePrice) || averagePrice < 0 || !investmentForm.operationDate) { toast.error(investmentForm.category === "fixed-income" ? "Preencha ticker, valor aplicado e data válidos" : "Preencha ticker, quantidade, preço médio e data válidos"); return; } const operation = { id: Date.now(), type: investmentForm.operationType, quantity: String(quantity), price: String(averagePrice), date: investmentForm.operationDate }; if (investmentForm.id) { setInvestments(current => current.map(item => { if (item.id !== investmentForm.id) return item; const baseDetails = item.institutionDetails?.length ? item.institutionDetails : [{ institution: item.institution, quantity: item.quantity, averagePrice: item.averagePrice, costBasis: String(investmentCost(item)), currentValue: String(investmentMarketValue(item)), profit: String(investmentProfitability(item).profit), profitabilityPercent: String(investmentProfitability(item).percent) }]; const conversion = investmentForm.category === "dollar" ? (Number(item.fxRate) || 1) : 1; if (investmentForm.institutionDetailIndex !== undefined) { const details = baseDetails.map((detail, index) => index === investmentForm.institutionDetailIndex ? { ...detail, institution: investmentForm.institution, quantity: String(quantity), averagePrice: String(averagePrice), costBasis: String(quantity * averagePrice), currentValue: String(quantity * (Number(item.marketPrice) || averagePrice) * conversion) } : detail); return recalculateConsolidatedInvestment(item, details, { ticker: investmentForm.ticker.trim().toUpperCase(), category: investmentForm.category, notes: investmentForm.notes, contractedRate: investmentForm.contractedRate, contractedBenchmark: investmentForm.contractedBenchmark, benchmarkAnnualRate: investmentForm.benchmarkAnnualRate }); } return { ...item, ticker: investmentForm.ticker.trim().toUpperCase(), category: investmentForm.category, institution: investmentForm.institution, quantity: String(quantity), averagePrice: String(averagePrice), currentValue: String((Number(item.marketPrice) ? quantity * Number(item.marketPrice) : quantity * averagePrice) * conversion), notes: investmentForm.notes, contractedRate: investmentForm.contractedRate, contractedBenchmark: investmentForm.contractedBenchmark, benchmarkAnnualRate: investmentForm.benchmarkAnnualRate, updatedAt: new Date().toISOString() }; })); toast.success("Posição atualizada"); } else { setInvestments(current => { const created = createLocalInvestment(current, { userId: Number(user.id), ticker: investmentForm.ticker.trim().toUpperCase(), category: investmentForm.category, institution: investmentForm.institution, quantity: "0", averagePrice: "0", currentValue: "0", operations: [], realizedProfit: "0", notes: investmentForm.notes, contractedRate: investmentForm.contractedRate, contractedBenchmark: investmentForm.contractedBenchmark, benchmarkAnnualRate: investmentForm.benchmarkAnnualRate }); const item = created[created.length - 1]; return created.map(entry => entry.id === item.id ? appendInvestmentOperation(item, operation) : entry); }); toast.success("Operação registrada; buscando cotação automaticamente"); } setInvestmentForm(null); }} />}
  </div>;
}

function BackupControls({ onExport, onImport }: { onExport: () => void; onImport: (event: React.ChangeEvent<HTMLInputElement>) => void }) {
  const inputRef = useRef<HTMLInputElement>(null);
  return <section className="mt-5 rounded-2xl border border-white/10 bg-white/[0.03] p-4"><div><p className="font-medium">Dados e backup</p><p className="mt-1 text-xs text-muted-foreground">Exporte todos os dados financeiros ou restaure uma cópia completa do Findash LVO.</p></div><input ref={inputRef} type="file" accept=".json,application/json" className="sr-only" onChange={onImport} /><div className="mt-4 grid gap-2 sm:grid-cols-2"><Button variant="outline" className="border-white/15 bg-white/[0.03]" onClick={onExport}><Download className="mr-2 h-4 w-4" />Exportar backup</Button><Button variant="outline" className="border-white/15 bg-white/[0.03]" onClick={() => inputRef.current?.click()}><CircleArrowUp className="mr-2 h-4 w-4" />Importar backup</Button></div></section>;
}

function ProfileDialog({ open, onOpenChange, user, sessionsQuery, revokeSession, revokeOtherSessions, onBackupExport, onBackupImport }: any) {
  const sessions = sessionsQuery.data?.sessions ?? [];
  const currentSessionId = sessionsQuery.data?.currentSessionId ?? null;
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="glass-modal max-h-[85vh] max-w-lg overflow-y-auto border-white/15"><DialogHeader><DialogTitle className="flex items-center gap-3"><Avatar className="h-11 w-11"><AvatarImage src={user.avatarUrl ?? undefined} alt={user.name ?? "Avatar do usuário"} /><AvatarFallback><UserRound className="h-5 w-5" /></AvatarFallback></Avatar><span>Perfil e segurança</span></DialogTitle><DialogDescription>Dados da sua conta Google e dispositivos com acesso ativo ao Findash LVO.</DialogDescription></DialogHeader><section className="rounded-2xl border border-white/10 bg-white/[0.03] p-4"><div className="flex items-center gap-3"><ShieldCheck className="h-5 w-5 text-emerald-300" /><div className="min-w-0"><p className="truncate font-medium">{user.name ?? "Usuário Google"}</p><p className="truncate text-sm text-muted-foreground">{user.email ?? "Conta Google autenticada"}</p></div></div><p className="mt-3 text-xs text-muted-foreground">A foto e o nome são atualizados automaticamente a partir do perfil Google autenticado.</p></section><BackupControls onExport={onBackupExport} onImport={onBackupImport} /><section className="mt-5"><div className="flex items-center justify-between gap-3"><div><p className="font-medium">Dispositivos conectados</p><p className="mt-1 text-xs text-muted-foreground">{sessionsQuery.isLoading ? "Carregando sessões…" : `${sessions.length} sessão(ões) ativa(s)`}</p></div><MonitorSmartphone className="h-5 w-5 text-primary" /></div>{sessionsQuery.error ? <div className="mt-4 rounded-2xl border border-dashed border-rose-400/30 p-4 text-sm text-rose-200">Não foi possível carregar os dispositivos conectados.</div> : sessionsQuery.isLoading ? <div className="mt-4 flex items-center justify-center gap-2 rounded-2xl border border-white/10 p-6 text-sm text-muted-foreground"><Loader2 className="h-4 w-4 animate-spin" />Consultando sessões…</div> : sessions.length ? <div className="mt-4 space-y-2">{sessions.map((session: any) => { const current = session.sessionId === currentSessionId; return <div key={session.sessionId} className="flex items-center gap-3 rounded-2xl border border-white/10 bg-white/[0.025] p-3"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-primary/10 text-primary">{session.deviceLabel?.toLowerCase().includes("móvel") ? <Smartphone className="h-4 w-4" /> : <MonitorSmartphone className="h-4 w-4" />}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-medium">{session.deviceLabel || "Navegador"}</p>{current && <span className="rounded-full bg-emerald-400/10 px-2 py-0.5 text-[10px] font-medium text-emerald-300">Este dispositivo</span>}</div><p className="mt-1 text-[11px] text-muted-foreground">Ativo em {new Date(session.lastSeenAt).toLocaleString("pt-BR")}</p></div>{!current && <Button variant="ghost" size="sm" className="shrink-0 text-rose-300 hover:bg-rose-400/10 hover:text-rose-200" disabled={revokeSession.isPending} onClick={() => revokeSession.mutate({ sessionId: session.sessionId })}>Encerrar</Button>}</div>; })}</div> : <div className="mt-4 rounded-2xl border border-dashed border-white/10 p-5 text-center text-sm text-muted-foreground">Nenhuma sessão ativa registrada.</div>}</section><DialogFooter className="mt-5 flex-col gap-2 sm:flex-row sm:justify-between"><Button variant="ghost" onClick={() => sessionsQuery.refetch()} disabled={sessionsQuery.isFetching}><RefreshCw className={`mr-2 h-4 w-4 ${sessionsQuery.isFetching ? "animate-spin" : ""}`} />Atualizar</Button><Button variant="outline" className="border-rose-400/30 text-rose-300 hover:bg-rose-400/10" disabled={!currentSessionId || revokeOtherSessions.isPending || sessions.length <= 1} onClick={() => revokeOtherSessions.mutate()}>Encerrar outras sessões</Button></DialogFooter></DialogContent></Dialog>;
}

function NavItem({ icon: Icon, label, active, onClick, collapsed }: { icon: any; label: string; active: boolean; onClick: () => void; collapsed?: boolean }) {
  return <button onClick={onClick} aria-label={label} aria-current={active ? "page" : undefined} className={`group relative flex w-full items-center rounded-xl px-3 py-3 text-sm transition-[background-color,color,box-shadow,transform] duration-200 ${collapsed ? "justify-center" : "gap-3"} ${active ? "bg-primary/20 text-primary shadow-lg shadow-primary/10 ring-1 ring-primary/20" : "text-muted-foreground hover:bg-white/5 hover:text-foreground"}`}><Icon className={`h-4 w-4 shrink-0 transition-transform duration-200 ${active ? "scale-110" : ""}`} />{!collapsed && label}{collapsed && <span role="tooltip" className="pointer-events-none invisible absolute left-[calc(100%+14px)] top-1/2 z-50 -translate-y-1/2 -translate-x-1 whitespace-nowrap rounded-lg border border-white/10 bg-[#1a1a20] px-3 py-2 text-sm font-medium text-foreground opacity-0 shadow-xl shadow-black/30 transition-[opacity,transform,visibility] duration-150 group-hover:visible group-hover:translate-x-0 group-hover:opacity-100 group-focus-visible:visible group-focus-visible:translate-x-0 group-focus-visible:opacity-100">{label}</span>}</button>;
}
function ExportMenu({ onJson, onExcel, onPdf, compact = false }: { onJson: () => void; onExcel: () => void; onPdf: () => void; compact?: boolean }) { return <DropdownMenu><DropdownMenuTrigger asChild><Button variant="outline" size="sm" className={`rounded-xl border-white/15 bg-white/[0.03] ${compact ? "flex-1" : ""}`}><Download className="mr-1.5 h-4 w-4" />Exportar</Button></DropdownMenuTrigger><DropdownMenuContent align="end" className="glass-panel min-w-48 border-white/15"><DropdownMenuItem onClick={onJson}><FileText className="h-4 w-4" />Backup completo JSON</DropdownMenuItem><DropdownMenuItem onClick={onExcel}><FileSpreadsheet className="h-4 w-4" />Excel</DropdownMenuItem><DropdownMenuItem onClick={onPdf}><FileText className="h-4 w-4" />PDF</DropdownMenuItem></DropdownMenuContent></DropdownMenu>; }
function Landing({ onLogin }: { onLogin: () => void }) { const [isLoggingIn, setIsLoggingIn] = useState(false); useEffect(() => { const params = new URLSearchParams(window.location.search); const error = params.get("oauth_error"); if (!error) return; const messages: Record<string, string> = { provider_denied: "O login Google foi cancelado. Você pode tentar novamente.", invalid_state: "A validação de segurança expirou. Inicie o login novamente.", authentication_failed: "Não foi possível concluir o login Google. Verifique a configuração e tente novamente." }; toast.error(messages[error] ?? "Não foi possível concluir o login Google."); window.history.replaceState({}, "", window.location.pathname); setIsLoggingIn(false); }, []); const handleLogin = () => { setIsLoggingIn(true); recordAuthEvent("login_started"); toast.info("Preparando o login seguro com Google…"); onLogin(); }; return <div className="grid min-h-screen place-items-center bg-[#0b0d12] p-6"><div className="w-full max-w-md text-center"><div className={`mx-auto mb-6 flex min-h-20 w-full max-w-[320px] items-center justify-center rounded-3xl bg-[#171326] p-4 shadow-2xl shadow-primary/25 transition-all duration-500 ${isLoggingIn ? "scale-[1.02] ring-1 ring-primary/40 shadow-primary/40" : ""}`}><img src={loginLogoUrl} alt="Findash LVO" className="h-auto w-full object-contain" loading="eager" decoding="async" /></div><p className="mb-3 text-sm font-medium uppercase tracking-[0.25em] text-primary">Findash LVO</p><h1 className="text-4xl font-semibold tracking-tight sm:text-5xl">Finanças sem ruído.</h1><p className="mx-auto mt-5 max-w-sm text-muted-foreground">Organize entradas, saídas e decisões em um painel simples, visual e feito para você.</p><Button onClick={handleLogin} disabled={isLoggingIn} size="lg" className={`mt-8 h-12 w-full rounded-xl transition-all duration-200 ${isLoggingIn ? "cursor-wait shadow-lg shadow-primary/25" : ""}`}>{isLoggingIn ? <><Loader2 className="mr-2 h-5 w-5 animate-spin" />Conectando ao Google...</> : "Entrar com Google"}</Button><div aria-live="polite" className={`mt-4 min-h-5 text-xs transition-opacity duration-300 ${isLoggingIn ? "text-primary opacity-100" : "text-muted-foreground opacity-100"}`}>{isLoggingIn ? "Você será redirecionado para concluir a autenticação com segurança." : "A autenticação segura carrega seu perfil automaticamente."}</div>{isLoggingIn && <div className="mx-auto mt-4 h-1.5 w-40 overflow-hidden rounded-full bg-white/10"><div className="h-full w-1/2 animate-pulse rounded-full bg-primary" /></div>}</div></div>; }
function InvestmentAllocationCard({ title, data }: { title: string; data: Array<{ name: string; value: number; currency?: "BRL" | "USD" }> }) { return <section className="glass-panel investment-card min-h-[240px] rounded-3xl border p-5"><div><p className="text-sm font-medium">{title}</p><p className="mt-1 text-xs text-muted-foreground">Distribuição pelo valor de mercado</p></div>{data.length ? <div className="mt-3 h-48"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={data} dataKey="value" nameKey="name" cx="50%" cy="48%" innerRadius={42} outerRadius={70} paddingAngle={3}>{data.map((entry, index) => <Cell key={entry.name} fill={chartColors[index % chartColors.length]} />)}</Pie><Tooltip formatter={(value: number, _name: string, payload: { payload?: { currency?: "BRL" | "USD" } }) => [(payload?.payload?.currency === "USD" ? usdMoney : money).format(value), "Valor"]} contentStyle={{ background: "#17131f", border: "1px solid rgba(255,255,255,.12)", borderRadius: 12, color: "#f8fafc" }} itemStyle={{ color: "#f8fafc" }} labelStyle={{ color: "#e9d5ff" }} /><Legend iconType="circle" wrapperStyle={{ fontSize: 10 }} /></PieChart></ResponsiveContainer></div> : <div className="grid h-48 place-items-center text-sm text-muted-foreground">Cadastre investimentos para visualizar.</div>}</section>; }
function InvestmentAnnualPerformanceCard({ investments, year, range, onRangeChange }: { investments: LocalInvestment[]; year: number; range: "week" | "month" | "year"; onRangeChange: (range: "week" | "month" | "year") => void }) {
  const today = new Date();
  const points = range === "year" ? Array.from({ length: 12 }, (_, month) => { const end = new Date(year, month + 1, 0, 12); return end > today ? new Date(today) : end; }) : range === "month" ? Array.from({ length: 6 }, (_, index) => { const date = new Date(today); date.setDate(today.getDate() - (5 - index) * 6); date.setHours(12, 0, 0, 0); return date; }) : Array.from({ length: 7 }, (_, index) => { const date = new Date(today); date.setDate(today.getDate() - (6 - index)); date.setHours(12, 0, 0, 0); return date; });
  const data = points.map((date, index) => ({ label: range === "year" ? monthNames[date.getMonth()] : date.toLocaleDateString("pt-BR", { day: "2-digit", month: "short" }), balance: year > today.getFullYear() || (range === "year" && year === today.getFullYear() && index > today.getMonth()) ? null : Number(investments.reduce((sum, item) => sum + investmentValueAtDate(item, date), 0).toFixed(2)) }));
  return <section className="glass-panel investment-card min-h-[340px] rounded-3xl border p-5 sm:p-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-sm font-medium">Performance dos investimentos</p><p className="mt-1 text-xs text-muted-foreground">Evolução acumulada em diferentes escalas</p></div><div className="flex rounded-xl border border-white/10 bg-white/[0.04] p-1">{([["week", "Semanal"], ["month", "Mensal"], ["year", "Anual"]] as const).map(([value, label]) => <button key={value} onClick={() => onRangeChange(value)} className={`rounded-lg px-2.5 py-1.5 text-xs transition ${range === value ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"}`}>{label}</button>)}</div></div>{investments.length ? <div className="mt-6 h-72"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data}><defs><linearGradient id="investmentPerformanceFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#c084fc" stopOpacity={0.38} /><stop offset="100%" stopColor="#c084fc" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="rgba(255,255,255,.06)" vertical={false} /><XAxis dataKey="label" axisLine={false} tickLine={false} tick={{ fill: "#8a91a4", fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#8a91a4", fontSize: 11 }} tickFormatter={value => `R$${Math.round(Number(value) / 1000)}k`} /><Tooltip contentStyle={{ background: "#17131f", border: "1px solid rgba(255,255,255,.12)", borderRadius: 14 }} formatter={(value: number) => [money.format(value), "Patrimônio"]} /><Area type="monotone" connectNulls={false} dataKey="balance" stroke="#d19aff" strokeWidth={3} fill="url(#investmentPerformanceFill)" /></AreaChart></ResponsiveContainer></div> : <div className="mt-6 grid h-72 place-items-center text-sm text-muted-foreground">Cadastre investimentos para visualizar.</div>}</section>;
}
function MarketWidgets({ quotes }: { quotes: Array<{ ticker: string; price?: number; changePercent?: number | null; ok: boolean; error?: string }> }) { return <section className="glass-panel dashboard-card min-h-[164px] rounded-3xl border p-5"><p className="text-sm font-medium">Cotações</p><p className="mt-1 text-xs text-muted-foreground">Atualizadas automaticamente</p><div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">{[{ ticker: "USD-BRL", label: "USD/BRL" }, { ticker: "EUR-BRL", label: "EUR/BRL" }, { ticker: "BTC", label: "BTC/BRL" }, { ticker: "ETH-BRL", label: "ETH/BRL" }].map(widget => { const quote = quotes.find(item => item.ticker === widget.ticker); const value = quote?.price; const positive = Number(quote?.changePercent ?? 0) >= 0; return <div key={widget.ticker} className="min-w-0 overflow-hidden rounded-2xl border border-white/10 bg-white/[0.03] p-2.5"><p className="truncate text-[11px] text-muted-foreground">{widget.label}</p><p className="mt-1 truncate text-sm font-semibold sm:text-base">{quote?.ok && value !== undefined ? money.format(value) : "—"}</p>{quote?.ok && quote.changePercent !== null && quote.changePercent !== undefined && <p className={`mt-1 flex items-center gap-1 text-xs font-medium ${positive ? "text-emerald-400" : "text-rose-400"}`}>{positive ? <ArrowUpRight className="h-3 w-3" /> : <ArrowDownRight className="h-3 w-3" />}{positive ? "+" : ""}{Number(quote.changePercent).toFixed(2)}%</p>}{quote && !quote.ok && <p className="mt-1 text-xs text-rose-400">Indisponível</p>}</div>; })}</div></section>; }
function Dashboard({ summary, transactions, month, year, selectedDate, paymentFilter, onPaymentFilterChange, performanceRange, onPerformanceRange, onSelectDate, onAdd, investments, onAddInvestment, onRefreshQuotes, quotesLoading, creditCards, onToggleCreditCardPaid, onAddCreditCard, marketWidgetQuotes }: any) {
  const aggregateByCategory = (type: "income" | "expense") => Object.entries(transactions.filter((item: LocalTransaction) => item.type === type).reduce((acc: Record<string, number>, item: LocalTransaction) => { const category = item.category?.trim() || "Sem categoria"; acc[category] = (acc[category] ?? 0) + Number(item.amount || 0); return acc; }, {})).map(([category, amount]) => ({ id: category, category, amount: Number(amount) })).sort((a, b) => b.amount - a.amount).slice(0, 1);
  const biggestExpenses = aggregateByCategory("expense");
  const biggestIncome = aggregateByCategory("income");
  const performance = buildPerformanceData(transactions, year, month, performanceRange, selectedDate);
  const allocationByType = (Object.entries(investments.reduce((acc: Record<string, { value: number; currency: "BRL" | "USD" }>, item: LocalInvestment) => {
    const label = investmentCategories.find(option => option.value === item.category)?.label ?? item.category;
    const currency = item.category === "dollar" ? "USD" : "BRL";
    const value = item.category === "dollar" ? investmentMarketValue(item) / (Number(item.fxRate) || 1) : investmentMarketValue(item);
    acc[label] = { value: (acc[label]?.value ?? 0) + value, currency };
    return acc;
  }, {})) as Array<[string, { value: number; currency: "BRL" | "USD" }]>).map(([name, entry]) => ({ name, value: Number(entry.value), currency: entry.currency }));
  const allocationByInstitution = (Object.values(investments.reduce((acc: Record<string, { name: string; value: number; currency: "BRL" | "USD" }>, item: LocalInvestment) => {
    investmentInstitutionAllocations(item).forEach(allocation => { const key = normalizeInstitutionName(allocation.name); const previous = acc[key]; acc[key] = { name: previous?.name ?? allocation.name, value: (previous?.value ?? 0) + allocation.value, currency: allocation.currency }; });
    return acc;
  }, {})) as Array<{ name: string; value: number; currency: "BRL" | "USD" }>).map(entry => ({ name: entry.name, value: Number(entry.value), currency: entry.currency }));
  const widgetMap: Record<DashboardWidgetKey, React.ReactNode> = {
    market: <MarketWidgets quotes={marketWidgetQuotes} />,
    currency: <section className="glass-panel rounded-3xl border p-5"><p className="text-sm font-medium">Carteira em moedas</p><p className="mt-1 text-xs text-muted-foreground">Ativos da categoria dólar são exibidos em USD nos seus cards individuais.</p><div className="mt-4 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-primary/10 p-3"><p className="text-xs text-muted-foreground">Posições</p><p className="mt-1 text-xl font-semibold">{investments.length}</p></div><div className="rounded-2xl bg-violet-400/10 p-3"><p className="text-xs text-muted-foreground">Categorias</p><p className="mt-1 text-xl font-semibold">{new Set(investments.map((item: LocalInvestment) => item.category)).size}</p></div></div></section>,
    expenses: <RankingCard title="Maiores gastos" items={biggestExpenses} empty="Nenhuma categoria de gasto cadastrada" tone="expense" />,
    income: <RankingCard title="Maiores entradas" items={biggestIncome} empty="Nenhuma categoria de entrada cadastrada" tone="income" />,
    nextInvoice: <NextInvoiceCard cards={creditCards} onTogglePaid={onToggleCreditCardPaid} onAdd={onAddCreditCard} />,
    allocationType: <InvestmentAllocationCard title="Investimentos por tipo" data={allocationByType} />,
    allocationInstitution: <InvestmentAllocationCard title="Investimentos por instituição" data={allocationByInstitution} />,
    periodSummary: <section className="glass-panel dashboard-card min-h-[136px] rounded-3xl border p-5"><p className="text-sm font-medium">Resumo do período</p><p className="mt-1 text-xs text-muted-foreground">Aplicações em investimentos seguem no saldo, mas não compõem as saídas exibidas.</p><div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-emerald-400/8 p-4"><p className="text-xs text-muted-foreground">Entradas</p><p className="mt-2 text-lg font-semibold text-emerald-300">{money.format(summary.income)}</p></div><div className="rounded-2xl bg-rose-400/8 p-4"><p className="text-xs text-muted-foreground">Saídas</p><p className="mt-2 text-lg font-semibold text-rose-300">{money.format(summary.expenseWithoutInvestments)}</p></div></div></section>,
  };
  const show = (key: DashboardWidgetKey) => widgetMap[key];
  const frame = (key: DashboardWidgetKey) => <div className="min-w-0">{widgetMap[key]}</div>;
  return <div className="space-y-6">
    <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-medium uppercase tracking-[0.24em] text-primary">Painel financeiro</p><h2 className="mt-1 text-2xl font-semibold tracking-tight sm:text-3xl">Uma visão clara do seu dinheiro</h2></div><div className="flex flex-wrap items-center justify-between gap-2 sm:justify-end"><p className="text-sm text-muted-foreground">{monthNames[month - 1]} de {year}</p><label className="flex items-center gap-2 rounded-xl border border-white/15 bg-white/[0.03] px-3 py-2 text-xs text-muted-foreground"><span>Método</span><select aria-label="Filtrar lançamentos por método de pagamento" className="bg-transparent text-foreground outline-none" value={paymentFilter} onChange={event => onPaymentFilterChange(event.target.value)}><option className="bg-[#10131b]" value="all">Todos</option><option className="bg-[#10131b]" value="cash">Dinheiro</option><option className="bg-[#10131b]" value="pix">Pix</option><option className="bg-[#10131b]" value="boleto">Boleto</option><option className="bg-[#10131b]" value="debit">Débito</option><option className="bg-[#10131b]" value="credit">Crédito</option></select></label></div></div>
    <div className="grid items-start gap-4 xl:grid-cols-3"><div className="min-w-0 h-fit space-y-4"><Metric title="Saldo no período" value={money.format(summary.income - summary.expense)} icon={Wallet} accent="text-primary" helper="Resultado líquido" /><div className="min-h-[360px]"><CalendarCard compact allTransactions={transactions} month={month} year={year} selectedDate={selectedDate} onSelectDate={onSelectDate} /></div></div><div className="min-w-0 h-fit space-y-4">{show("expenses")}{show("income")}{show("nextInvoice")}</div><div className="min-w-0 h-fit space-y-4"><InvestmentCard investments={investments} onAdd={onAddInvestment} onRefreshQuotes={onRefreshQuotes} quotesLoading={quotesLoading} /></div></div>
    <div className="grid items-start gap-4 xl:grid-cols-3"><div className="min-w-0">{frame("periodSummary")}</div><div className="min-w-0 xl:col-span-2">{frame("market")}</div></div>
    <div className="grid items-stretch gap-4 md:grid-cols-2">{frame("allocationType")}{frame("allocationInstitution")}</div>
    <div className="min-w-0"><PerformanceCard data={performance} range={performanceRange} onRangeChange={onPerformanceRange} /></div>
    <div className="min-w-0"><InvestmentAnnualPerformanceCard investments={investments} year={year} range={performanceRange} onRangeChange={onPerformanceRange} /></div>
  </div>;
}

function RankingCard({ title, items, empty, tone }: any) { return <section className="glass-panel dashboard-card min-h-[136px] rounded-3xl border p-5"><div className="flex items-start justify-between"><div><p className="text-sm font-medium">{title}</p><p className="mt-1 text-xs text-muted-foreground">Agregado por categoria no período</p></div>{tone === "income" ? <ArrowUpRight className="h-5 w-5 text-emerald-400" /> : <ArrowDownRight className="h-5 w-5 text-rose-400" />}</div><div className="mt-5">{items.length ? <div className="flex items-center gap-3" key={items[0].id}><span className={`grid h-7 w-7 place-items-center rounded-lg text-xs font-semibold ${tone === "income" ? "bg-emerald-400/10 text-emerald-300" : "bg-rose-400/10 text-rose-300"}`}>1</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{items[0].category || "Sem categoria"}</p><p className="text-xs text-muted-foreground">Total da categoria</p></div><strong className={`text-sm ${tone === "income" ? "text-emerald-300" : "text-rose-300"}`}>{money.format(Number(items[0].amount))}</strong></div> : <div className="rounded-2xl border border-dashed border-white/10 px-3 py-3 text-center"><p className="text-sm text-muted-foreground">{empty}</p><p className="mt-1 text-xs text-muted-foreground">Cadastre um lançamento para visualizar o ranking.</p></div>}</div></section>; }

function InvestmentCard({ investments, onAdd, onRefreshQuotes, quotesLoading }: any) { const total = investments.reduce((sum: number, item: LocalInvestment) => sum + investmentMarketValue(item), 0); const cost = investments.reduce((sum: number, item: LocalInvestment) => sum + investmentCost(item), 0); const latestQuote = [...investments].filter(item => item.quoteFetchedAt).sort((a, b) => String(b.quoteFetchedAt).localeCompare(String(a.quoteFetchedAt)))[0]; const topInvestments = [...investments].sort((a, b) => investmentMarketValue(b) - investmentMarketValue(a)).slice(0, 10); return <section className="glass-panel dashboard-card investment-card min-h-[560px] relative overflow-hidden rounded-3xl border p-5"><div className="absolute -right-10 -top-10 h-32 w-32 rounded-full bg-primary/15 blur-3xl" /><div className="flex items-start justify-between"><div><p className="text-sm font-medium">Carteira de investimentos</p><p className="mt-1 text-xs text-muted-foreground">Valor de mercado acompanhado</p></div><BriefcaseBusiness className="h-5 w-5 text-primary" /></div><div className="mt-6"><p className="text-2xl font-semibold">{investments.length ? money.format(total) : "—"}</p><p className="mt-1 text-xs text-muted-foreground">Custo total: {investments.length ? money.format(cost) : "—"}</p><p className="mt-1 text-xs text-muted-foreground">{investments.length ? `${investments.length} posição(ões)` : "Nenhuma posição cadastrada"}</p><p className="mt-2 text-[11px] text-muted-foreground">{latestQuote?.quoteFetchedAt ? latestQuote.quoteError ? `Cotação indisponível: ${latestQuote.quoteError}` : <>{`Última cotação: ${new Date(latestQuote.quoteFetchedAt).toLocaleString("pt-BR")} · ${latestQuote.quoteSource ?? "brapi.dev"}`}{latestQuote.quoteChangePercent !== undefined && <UiTooltip><TooltipTrigger asChild><span tabIndex={0} aria-label="Ver fechamento anterior" className={`ml-1 inline-flex cursor-help items-center gap-0.5 font-medium outline-none focus-visible:rounded focus-visible:ring-2 focus-visible:ring-primary ${Number(latestQuote.quoteChangePercent) >= 0 ? "text-emerald-400" : "text-rose-400"}`}>{Number(latestQuote.quoteChangePercent) >= 0 ? <ArrowUpRight className="h-3 w-3" /> : <ArrowDownRight className="h-3 w-3" />}{Number(latestQuote.quoteChangePercent) >= 0 ? "+" : ""}{Number(latestQuote.quoteChangePercent).toFixed(2)}%</span></TooltipTrigger><TooltipContent>Fechamento anterior: {latestQuote.quotePreviousClose !== undefined ? money.format(Number(latestQuote.quotePreviousClose)) : "indisponível"}</TooltipContent></UiTooltip>}</> : "Última cotação: ainda não atualizada"}</p></div><div className="mt-5 grid grid-cols-2 gap-2"><Button variant="secondary" size="sm" className="rounded-xl" onClick={onAdd}><Plus className="mr-2 h-4 w-4" />Cadastrar</Button><Button variant="ghost" size="sm" className="rounded-xl" onClick={onRefreshQuotes} disabled={quotesLoading || !investments.some((item: LocalInvestment) => item.ticker)}>{quotesLoading ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Atualizando…</> : "Atualizar"}</Button></div>{topInvestments.length > 0 && <div className="mt-5 space-y-2 border-t border-white/8 pt-4"><div className="flex items-center justify-between"><p className="text-xs font-medium text-muted-foreground">Maiores ativos</p><span className="text-[11px] text-muted-foreground">{topInvestments.length} de {investments.length}</span></div><div className="max-h-64 space-y-1.5 overflow-y-auto pr-1">{topInvestments.map((item: LocalInvestment) => <div key={item.id} className="flex items-center justify-between gap-3 rounded-xl bg-white/[0.03] px-3 py-2 text-xs"><span className="min-w-0 truncate font-medium">{item.ticker || item.name || "Ativo"}</span><strong className="shrink-0">{formatInvestmentMoney(item, investmentMarketValue(item))}</strong></div>)}</div></div>}</section>; }
function AssetPerformanceChart({ ticker, options, onTickerChange, data, loading, range, onRangeChange, error }: { ticker: string; options: string[]; onTickerChange: (ticker: string) => void; data: Array<{ date: number; close: number; assetEffect?: number; fxEffect?: number }>; loading: boolean; range: "1mo" | "6mo" | "1y"; onRangeChange: (range: "1mo" | "6mo" | "1y") => void; error?: string }) { const hasBreakdown = data.some(point => Number.isFinite(point.assetEffect) || Number.isFinite(point.fxEffect)); const firstTotal = data.find(point => Number.isFinite(point.close) && point.close > 0)?.close ?? 0; const firstAsset = data.find(point => Number.isFinite(point.assetEffect) && (point.assetEffect ?? 0) > 0)?.assetEffect ?? 0; const firstFx = data.find(point => Number.isFinite(point.fxEffect) && (point.fxEffect ?? 0) > 0)?.fxEffect ?? 0; const chartData = data.map(point => ({ date: new Date(point.date * 1000).toLocaleDateString("pt-BR", { month: "short", day: "2-digit" }), totalBrl: point.close, assetEffect: point.assetEffect, fxEffect: point.fxEffect, totalPct: firstTotal > 0 ? ((point.close / firstTotal) - 1) * 100 : undefined, assetPct: firstAsset > 0 && Number.isFinite(point.assetEffect) ? (((point.assetEffect as number) / firstAsset) - 1) * 100 : undefined, fxPct: firstFx > 0 && Number.isFinite(point.fxEffect) ? (((point.fxEffect as number) / firstFx) - 1) * 100 : undefined })); return <section className="glass-panel rounded-3xl border p-5 sm:p-6"><div className="flex items-start justify-between"><div><p className="text-sm font-medium">Desempenho histórico</p><p className="mt-1 text-xs text-muted-foreground">{ticker ? `${ticker === "__ALL__" ? "Todos os ativos" : ticker} · fechamento diário · ${range === "1mo" ? "1 mês" : range === "6mo" ? "6 meses" : "1 ano"}` : "Cadastre um ativo com ticker"}</p></div><div className="flex flex-wrap items-center gap-2">{options.length > 1 && <select className="rounded-lg border border-white/10 bg-white/[0.04] px-2 py-1 text-xs outline-none" value={ticker} onChange={event => onTickerChange(event.target.value)}>{options.map(option => <option className="bg-[#10131b]" key={option} value={option}>{option === "__ALL__" ? "Todos os ativos" : option}</option>)}</select>}<div className="flex rounded-lg border border-white/10 bg-white/[0.04] p-0.5">{([["1mo", "1 mês"], ["6mo", "6 meses"], ["1y", "1 ano"]] as const).map(([value, label]) => <button type="button" key={value} onClick={() => onRangeChange(value)} className={`rounded-md px-2 py-1 text-[11px] transition ${range === value ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"}`}>{label}</button>)}</div></div></div>{loading ? <div className="grid h-56 place-items-center text-sm text-muted-foreground">Carregando histórico…</div> : error ? <div className="mt-5 rounded-2xl border border-dashed border-rose-400/20 p-6 text-center text-sm text-muted-foreground">Histórico indisponível: {error}</div> : chartData.length ? <div className="mt-5 h-56"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={chartData}><defs><linearGradient id="assetPerformance" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#a855f7" stopOpacity={0.35} /><stop offset="95%" stopColor="#a855f7" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="rgba(255,255,255,0.08)" vertical={false} /><XAxis dataKey="date" tick={{ fill: "#94a3b8", fontSize: 10 }} tickLine={false} axisLine={false} minTickGap={28} /><YAxis yAxisId="brl" tick={{ fill: "#94a3b8", fontSize: 10 }} tickLine={false} axisLine={false} width={54} /><YAxis yAxisId="pct" orientation="right" tick={{ fill: "#94a3b8", fontSize: 10 }} tickLine={false} axisLine={false} width={48} tickFormatter={(value: number) => `${value.toFixed(0)}%`} /><Tooltip contentStyle={{ background: "#151622", border: "1px solid rgba(255,255,255,0.12)", borderRadius: 12 }} formatter={(value: number, name: string) => [name.endsWith("Pct") ? `${Number(value).toFixed(2)}%` : money.format(value), name === "totalBrl" ? "Total em BRL" : name === "assetEffect" ? "Variação do ativo" : name === "fxEffect" ? "Efeito cambial" : name === "totalPct" ? "Total acumulado" : name === "assetPct" ? "Ativo acumulado" : "Câmbio acumulado"]} /><Area yAxisId="brl" type="monotone" dataKey="totalBrl" name="Total em BRL" stroke="#c084fc" fill="url(#assetPerformance)" strokeWidth={2} />{hasBreakdown && <><Line yAxisId="brl" type="monotone" dataKey="assetEffect" name="Variação do ativo" stroke="#22d3ee" strokeWidth={2} dot={false} connectNulls /><Line yAxisId="brl" type="monotone" dataKey="fxEffect" name="Efeito cambial" stroke="#fbbf24" strokeWidth={2} dot={false} connectNulls /><Line yAxisId="pct" type="monotone" dataKey="totalPct" name="Total acumulado" stroke="#f472b6" strokeWidth={2} dot={false} connectNulls strokeDasharray="5 4" /><Line yAxisId="pct" type="monotone" dataKey="assetPct" name="Ativo acumulado" stroke="#67e8f9" strokeWidth={2} dot={false} connectNulls strokeDasharray="5 4" /><Line yAxisId="pct" type="monotone" dataKey="fxPct" name="Câmbio acumulado" stroke="#fde68a" strokeWidth={2} dot={false} connectNulls strokeDasharray="5 4" /><Legend wrapperStyle={{ color: "#cbd5e1", fontSize: 11 }} /></>}</ComposedChart></ResponsiveContainer></div> : <div className="mt-5 rounded-2xl border border-dashed border-white/10 p-6 text-center text-sm text-muted-foreground">Nenhum histórico disponível para este ticker.</div>}</section>; }

function CalendarCard({ allTransactions, month, year, selectedDate, onSelectDate, compact = false }: any) {
  const [detailDate, setDetailDate] = useState<string | null>(null);
  const [dueBudgets, setDueBudgets] = useState<MonthlyBudget[]>([]);
  const daysInMonth = new Date(year, month, 0).getDate();
  const firstDay = (new Date(year, month - 1, 1).getDay() + 6) % 7;
  const byDate = new Map<string, LocalTransaction[]>();
  allTransactions.forEach((item: LocalTransaction) => {
    const key = new Date(item.occurredAt).toISOString().slice(0, 10);
    byDate.set(key, [...(byDate.get(key) ?? []), item]);
  });
  useEffect(() => {
    const sync = (event: Event) => setDueBudgets((event as CustomEvent<MonthlyBudget[]>).detail ?? []);
    window.addEventListener("findash:budget-calendar-sync", sync as EventListener);
    window.dispatchEvent(new Event("findash:budget-calendar-request"));
    return () => window.removeEventListener("findash:budget-calendar-sync", sync as EventListener);
  }, []);
  const dueForDate = (date: string) => dueBudgets.filter(budget => {
    const status = budgetDueAlert(budget, 0).dueStatus;
    return budget.month === date.slice(0, 7) && budget.kind === "fixed" && budget.dueDay === Number(date.slice(-2)) && ["scheduled", "due-soon", "due-today"].includes(status);
  });
  useEffect(() => {
    const buttons = Array.from(document.querySelectorAll<HTMLButtonElement>(`button[aria-label^="Ver lançamentos de"]`));
    buttons.forEach(button => {
      button.querySelectorAll("[data-budget-due-marker]").forEach(marker => marker.remove());
      const day = Number(button.getAttribute("aria-label")?.match(/de (\d{1,2}) de/)?.[1]);
      const date = `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
      if (Number.isInteger(day) && dueForDate(date).length) {
        const marker = document.createElement("i");
        marker.dataset.budgetDueMarker = "true";
        marker.className = "absolute right-1 top-1 h-1.5 w-1.5 rounded-full bg-amber-300 shadow-sm shadow-amber-300/80";
        marker.setAttribute("aria-label", "Há vencimento nesta data");
        button.appendChild(marker);
      }
    });
  }, [dueBudgets, month, year]);
  const selectDay = (date: string) => {
    onSelectDate(date);
    setDetailDate(date);
    const due = dueForDate(date);
    if (due.length) toast.info(`Vencimento: ${due.map(item => item.category).join(", ")}`);
  };
  return <><section className={`glass-panel rounded-3xl border ${compact ? "p-4" : "p-5 sm:p-6"}`}><div className="flex items-start justify-between"><div><p className="text-sm font-medium">Calendário financeiro</p><p className="mt-1 text-xs text-muted-foreground">Selecione um dia para ver os lançamentos</p></div><CalendarDays className="h-5 w-5 text-primary" /></div><div className={`${compact ? "mt-3 gap-0.5" : "mt-5 gap-1"} grid grid-cols-7 text-center text-[11px] text-muted-foreground`}>{["S", "T", "Q", "Q", "S", "S", "D"].map((label, index) => <span key={`${label}-${index}`} className="py-1">{label}</span>)}{Array.from({ length: firstDay }).map((_, index) => <span key={`blank-${index}`} />)}{Array.from({ length: daysInMonth }, (_, index) => index + 1).map(day => { const key = `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`; const entries = byDate.get(key) ?? []; const active = selectedDate === key; return <button key={key} type="button" onClick={() => selectDay(key)} aria-label={`Ver lançamentos de ${day} de ${monthNames[month - 1]} de ${year}`} className={`relative grid aspect-square place-items-center rounded-xl ${compact ? "text-xs" : "text-sm"} transition-[background-color,color,transform,box-shadow] duration-200 active:scale-95 ${active ? "bg-primary text-primary-foreground shadow-lg shadow-primary/20" : "hover:bg-white/8"}`}>{day}{entries.length > 0 && <span className={`absolute bottom-1 h-1 w-1 rounded-full ${entries.some(item => item.type === "income") ? "bg-emerald-400" : "bg-rose-400"}`} />}</button>; })}</div><div className="mt-4 flex items-center gap-4 text-[11px] text-muted-foreground"><span className="flex items-center gap-1.5"><i className="h-1.5 w-1.5 rounded-full bg-emerald-400" />Entradas</span><span className="flex items-center gap-1.5"><i className="h-1.5 w-1.5 rounded-full bg-rose-400" />Saídas</span></div></section><DayTransactionsDialog date={detailDate} transactions={detailDate ? filterCalendarDayTransactions(allTransactions, detailDate) : []} onClose={() => setDetailDate(null)} /></>;
}

function DayTransactionsDialog({ date, transactions, onClose }: { date: string | null; transactions: LocalTransaction[]; onClose: () => void }) {
  const [dueBudgets, setDueBudgets] = useState<MonthlyBudget[]>([]);
  const income = transactions.filter(item => item.type === "income").reduce((total, item) => total + Number(item.amount), 0);
  const expense = transactions.filter(item => item.type === "expense").reduce((total, item) => total + Number(item.amount), 0);
  const formattedDate = date ? new Date(`${date}T12:00:00`).toLocaleDateString("pt-BR", { weekday: "long", day: "2-digit", month: "long", year: "numeric" }) : "";
  const dueItems = date ? dueBudgets.filter(budget => budget.month === date.slice(0, 7) && budget.kind === "fixed" && budget.dueDay === Number(date.slice(-2)) && budgetDueAlert(budget, 0).dueStatus !== "settled") : [];
  useEffect(() => {
    const sync = (event: Event) => setDueBudgets((event as CustomEvent<MonthlyBudget[]>).detail ?? []);
    window.addEventListener("findash:budget-calendar-sync", sync as EventListener);
    window.dispatchEvent(new Event("findash:budget-calendar-request"));
    return () => window.removeEventListener("findash:budget-calendar-sync", sync as EventListener);
  }, []);
  useEffect(() => {
    const dialog = document.querySelector<HTMLElement>("[role=dialog]");
    dialog?.querySelector("[data-calendar-due-notice]")?.remove();
    if (!dialog || !dueItems.length) return;
    const notice = document.createElement("div");
    notice.dataset.calendarDueNotice = "true";
    notice.className = "rounded-2xl border border-amber-300/30 bg-amber-300/10 p-3 text-sm text-amber-100";
    const title = document.createElement("p");
    title.className = "font-semibold";
    title.textContent = "Vencimento nesta data";
    const detail = document.createElement("p");
    detail.className = "mt-1 text-xs text-amber-100/80";
    detail.textContent = dueItems.map(item => `${item.category} · ${money.format(Number(item.plannedAmount))}`).join(" | ");
    const actions = document.createElement("div");
    actions.className = "mt-3 flex flex-wrap gap-2";
    dueItems.forEach(item => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "rounded-lg bg-emerald-400/15 px-2.5 py-1.5 text-xs font-semibold text-emerald-100 transition hover:bg-emerald-400/25";
      button.textContent = `Marcar ${item.category} como pago`;
      button.onclick = () => {
        window.dispatchEvent(new CustomEvent("findash:budget-payment-update", { detail: { id: item.id, paid: true } }));
        toast.success(`${item.category} marcada como paga`);
      };
      actions.appendChild(button);
    });
    notice.append(title, detail, actions);
    dialog.prepend(notice);
  }, [date, dueItems]);
  return <Dialog open={Boolean(date)} onOpenChange={open => { if (!open) onClose(); }}><DialogContent className="glass-modal max-h-[85vh] max-w-xl overflow-y-auto border-white/15 p-5 shadow-2xl shadow-black/40 sm:p-6"><DialogHeader><p className="text-xs font-medium uppercase tracking-[0.22em] text-primary">Detalhes do dia</p><DialogTitle className="capitalize">{formattedDate}</DialogTitle><DialogDescription>{transactions.length ? `${transactions.length} lançamento(s) registrado(s) nesta data.` : "Ainda não há lançamentos registrados nesta data."}</DialogDescription></DialogHeader>{transactions.length > 0 ? <><div className="grid grid-cols-2 gap-3"><div className="rounded-2xl border border-emerald-400/15 bg-emerald-400/[0.07] p-4"><p className="text-xs text-muted-foreground">Entradas</p><p className="mt-1 text-lg font-semibold text-emerald-300">{money.format(income)}</p></div><div className="rounded-2xl border border-rose-400/15 bg-rose-400/[0.07] p-4"><p className="text-xs text-muted-foreground">Saídas</p><p className="mt-1 text-lg font-semibold text-rose-300">{money.format(expense)}</p></div></div><div className="mt-1 space-y-2">{transactions.map(item => <article key={item.id} className="flex items-center gap-3 rounded-2xl border border-white/8 bg-white/[0.035] p-3"><div className={`grid h-10 w-10 shrink-0 place-items-center rounded-xl ${item.type === "income" ? "bg-emerald-400/10 text-emerald-300" : "bg-rose-400/10 text-rose-300"}`}><span className="text-base">{item.icon || (item.type === "income" ? "↗" : "◒")}</span></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{item.description || item.store || "Lançamento"}</p><p className="mt-0.5 truncate text-xs text-muted-foreground">{item.category || "Sem categoria"}{item.store && item.description ? ` · ${item.store}` : ""}{item.product ? ` · ${item.product}` : ""}</p></div><p className={`shrink-0 text-sm font-semibold ${item.type === "income" ? "text-emerald-300" : "text-rose-300"}`}>{item.type === "income" ? "+" : "−"}{money.format(Number(item.amount))}</p></article>)}</div></> : <div className="grid min-h-44 place-items-center rounded-2xl border border-dashed border-white/15 bg-white/[0.025] p-6 text-center"><div><CalendarDays className="mx-auto h-7 w-7 text-primary/80" /><p className="mt-3 text-sm font-medium">Nenhum lançamento neste dia</p><p className="mt-1 text-xs text-muted-foreground">Use o botão “+” para registrar uma entrada ou saída nesta data.</p></div></div>}<DialogFooter className="mt-2"><Button type="button" variant="outline" className="border-white/15 bg-white/[0.03]" onClick={onClose}>Fechar</Button></DialogFooter></DialogContent></Dialog>;
}


function buildPerformanceData(transactions: LocalTransaction[], year: number, month: number, range: "week" | "month" | "year", selectedDate: string) { const points = range === "year" ? monthNames.map((label, index) => ({ label, start: new Date(year, index, 1), end: new Date(year, index + 1, 0, 23, 59, 59) })) : range === "month" ? Array.from({ length: new Date(year, month, 0).getDate() }, (_, index) => ({ label: String(index + 1), start: new Date(year, month - 1, index + 1), end: new Date(year, month - 1, index + 1, 23, 59, 59) })) : Array.from({ length: 7 }, (_, index) => { const end = new Date(`${selectedDate}T12:00:00`); end.setDate(end.getDate() - (6 - index)); return { label: end.toLocaleDateString("pt-BR", { weekday: "short" }).replace(".", ""), start: new Date(end.getFullYear(), end.getMonth(), end.getDate()), end: new Date(end.getFullYear(), end.getMonth(), end.getDate(), 23, 59, 59) }; }); let balance = 0; return points.map(point => { transactions.filter(item => { const date = new Date(item.occurredAt); return date >= point.start && date <= point.end; }).forEach(item => { balance += item.type === "income" ? Number(item.amount) : -Number(item.amount); }); return { month: point.label, balance }; }); }

function PerformanceCard({ data, range, onRangeChange }: any) { return <section className="glass-panel rounded-3xl border p-5 sm:p-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-sm font-medium">Performance financeira</p><p className="mt-1 text-xs text-muted-foreground">Evolução acumulada em diferentes escalas</p></div><div className="flex rounded-xl border border-white/10 bg-white/[0.04] p-1">{([["week", "Semanal"], ["month", "Mensal"], ["year", "Anual"]] as const).map(([value, label]) => <button key={value} onClick={() => onRangeChange(value)} className={`rounded-lg px-2.5 py-1.5 text-xs transition ${range === value ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"}`}>{label}</button>)}</div></div><div className="mt-6 h-72"><ResponsiveContainer width="100%" height="100%"><AreaChart data={data}><defs><linearGradient id="performanceFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#c084fc" stopOpacity={0.38} /><stop offset="100%" stopColor="#c084fc" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="rgba(255,255,255,.06)" vertical={false} /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: "#8a91a4", fontSize: 11 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#8a91a4", fontSize: 11 }} tickFormatter={value => `R$${Math.round(value / 1000)}k`} /><Tooltip contentStyle={{ background: "#17131f", border: "1px solid rgba(255,255,255,.12)", borderRadius: 14 }} formatter={(value: number) => money.format(value)} /><Area type="monotone" dataKey="balance" stroke="#d19aff" strokeWidth={3} fill="url(#performanceFill)" /></AreaChart></ResponsiveContainer></div></section>; }
function Metric({ title, value, icon: Icon, accent }: any) { return <div className="glass-panel min-h-[104px] rounded-3xl border p-5"><div className="flex items-center justify-between"><p className="text-sm text-muted-foreground">{title}</p><Icon className={`h-5 w-5 ${accent}`} /></div><p className="mt-5 text-2xl font-semibold tracking-tight">{value}</p></div>; }
function TransactionsPage({ grouped, invoiceMonthMode, onInvoiceMonthModeChange, onEdit, onDelete }: any) { return <div className="space-y-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><h2 className="text-2xl font-semibold">Entradas e saídas</h2><p className="mt-1 text-sm text-muted-foreground">Gerencie cada movimento do seu mês.</p></div><div className="flex flex-wrap items-center gap-2"><div className="flex rounded-xl border border-white/10 bg-white/[0.04] p-1"><button type="button" onClick={() => onInvoiceMonthModeChange("calendar")} className={`rounded-lg px-3 py-1.5 text-xs transition ${invoiceMonthMode === "calendar" ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"}`}>Mês corrido</button><button type="button" onClick={() => onInvoiceMonthModeChange("invoice")} className={`rounded-lg px-3 py-1.5 text-xs transition ${invoiceMonthMode === "invoice" ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"}`}>Mês da fatura</button></div><p className="text-sm text-muted-foreground">{grouped.income.length + grouped.expense.length} registros</p></div></div>{invoiceMonthMode === "invoice" && <p className="rounded-2xl border border-primary/20 bg-primary/[0.06] px-4 py-3 text-xs text-muted-foreground">As despesas no crédito são agrupadas pela competência da fatura; os demais lançamentos continuam usando a data ocorrida.</p>}<div className="grid gap-6 xl:grid-cols-2"><TransactionColumn title="Entradas" subtitle="Receitas, salários e ganhos" items={grouped.income} tone="income" onEdit={onEdit} onDelete={onDelete} /><TransactionColumn title="Saídas" subtitle={invoiceMonthMode === "invoice" ? "Compras agrupadas por fatura" : "Despesas e compromissos"} items={grouped.expense} tone="expense" onEdit={onEdit} onDelete={onDelete} /></div></div>; }
function TransactionColumn({ title, subtitle, items, tone, onEdit, onDelete }: any) { const palette = ["#34d399", "#a78bfa", "#60a5fa", "#fbbf24", "#fb7185", "#22d3ee"]; const [categoryFilter, setCategoryFilter] = useState<string | null>(null); const [collapsedDays, setCollapsedDays] = useState<Set<string>>(() => new Set(items.map((item: any) => new Date(item.occurredAt).toISOString().slice(0, 10)))); const categoryMap = new Map<string, number>(); items.forEach((item: any) => { const category = item.category || "Sem categoria"; categoryMap.set(category, (categoryMap.get(category) ?? 0) + Number(item.amount)); }); const categories = Array.from(categoryMap.entries()).map(([name, value]) => ({ name, value })); const filteredItems = categoryFilter ? items.filter((item: any) => (item.category || "Sem categoria") === categoryFilter) : items; const dayMap = new Map<string, any[]>(); filteredItems.forEach((item: any) => { const day = new Date(item.occurredAt).toISOString().slice(0, 10); dayMap.set(day, [...(dayMap.get(day) ?? []), item]); }); const byDay = Array.from(dayMap.entries()).sort(([a], [b]) => b.localeCompare(a)); const toggleDay = (day: string) => setCollapsedDays(current => { const next = new Set(current); next.has(day) ? next.delete(day) : next.add(day); return next; }); const allCollapsed = byDay.length > 0 && byDay.every(([day]) => collapsedDays.has(day)); return <section className="glass-panel rounded-3xl border p-5 sm:p-6"><div className="flex items-center gap-3"><div className={`grid h-10 w-10 place-items-center rounded-2xl ${tone === "income" ? "bg-emerald-400/12 text-emerald-400" : "bg-rose-400/12 text-rose-400"}`}>{tone === "income" ? <CircleArrowUp className="h-5 w-5" /> : <CircleArrowDown className="h-5 w-5" />}</div><div><h3 className="font-semibold">{title}</h3><p className="text-xs text-muted-foreground">{subtitle}</p></div></div>{categories.length > 0 && <div className="mt-4 flex items-center gap-3 rounded-2xl border border-white/8 bg-white/[0.025] p-3"><ResponsiveContainer width={96} height={96}><PieChart><Pie data={categories} dataKey="value" innerRadius={27} outerRadius={42} paddingAngle={3} cursor="pointer" onClick={(entry: any) => setCategoryFilter(current => current === entry.name ? null : entry.name)}>{categories.map((item, index) => <Cell key={item.name} fill={palette[index % palette.length]} opacity={!categoryFilter || categoryFilter === item.name ? 1 : 0.3} />)}</Pie><Tooltip formatter={(value: number) => money.format(value)} contentStyle={{ background: "#17131f", border: "1px solid rgba(255,255,255,.12)", borderRadius: 12 }} /></PieChart></ResponsiveContainer><div className="min-w-0 flex-1 space-y-1">{categories.slice(0, 4).map((item, index) => <button type="button" key={item.name} onClick={() => setCategoryFilter(current => current === item.name ? null : item.name)} className={`flex w-full items-center justify-between gap-2 rounded px-1 py-0.5 text-left text-xs transition ${categoryFilter === item.name ? "bg-white/10" : "hover:bg-white/[0.06]"}`}><span className="flex min-w-0 items-center gap-1.5 truncate"><i className="h-2 w-2 shrink-0 rounded-full" style={{ backgroundColor: palette[index % palette.length] }} />{item.name}</span><strong>{money.format(item.value)}</strong></button>)}</div></div>}{categoryFilter && <button type="button" className="mt-2 text-xs font-medium text-primary hover:underline" onClick={() => setCategoryFilter(null)}>Limpar filtro: {categoryFilter}</button>}<div className="mt-5 flex justify-end"><Button type="button" variant="ghost" size="sm" className="h-8 text-xs text-muted-foreground" onClick={() => setCollapsedDays(allCollapsed ? new Set() : new Set(byDay.map(([day]) => day)))}>{allCollapsed ? "Expandir dias" : "Recolher dias"}</Button></div><div className="mt-2 space-y-5">{byDay.length ? byDay.map(([day, entries]) => { const dailyTotal = entries.reduce((sum: number, item: any) => sum + Number(item.amount), 0); const collapsed = collapsedDays.has(day); return <div key={day}><button type="button" onClick={() => toggleDay(day)} className="mb-2 flex w-full items-center justify-between border-b border-white/8 pb-2 text-left"><span className="text-xs font-semibold capitalize text-muted-foreground">{new Date(`${day}T12:00:00`).toLocaleDateString("pt-BR", { weekday: "long", day: "2-digit", month: "short" })}</span><span className="flex items-center gap-2 text-[11px] text-muted-foreground"><strong className={tone === "income" ? "text-emerald-300" : "text-rose-300"}>{tone === "income" ? "+" : "−"}{money.format(dailyTotal)}</strong>{entries.length} lançamento(s)<ChevronDown className={`h-3.5 w-3.5 transition-transform ${collapsed ? "-rotate-90" : ""}`} /></span></button>{!collapsed && <div className="space-y-1">{entries.map((item: any) => <TransactionRow key={item.id} item={item} actions onEdit={onEdit} onDelete={onDelete} />)}</div>}</div>; }) : <p className="rounded-2xl border border-dashed border-white/10 py-10 text-center text-sm text-muted-foreground">Nenhum registro para este filtro.</p>}</div></section>; }
function TransactionRow({ item, actions, onEdit, onDelete }: any) { return <div className="group flex items-center gap-3 rounded-2xl px-3 py-3 transition-colors hover:bg-white/[0.04]"><div className={`grid h-9 w-9 shrink-0 place-items-center rounded-xl ${item.type === "income" ? "bg-emerald-400/10 text-emerald-400" : "bg-rose-400/10 text-rose-400"}`}><span className="text-sm">{item.icon || (item.type === "income" ? "↗" : "◒")}</span></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{item.description}</p><p className="text-xs text-muted-foreground">{item.category} · {new Date(item.occurredAt).toLocaleDateString("pt-BR")}{item.paymentMethod === "credit" && ` · Fatura ${item.invoiceMonth ?? new Date(item.occurredAt).toISOString().slice(0, 7)}`}</p></div><p className={`text-sm font-semibold ${item.type === "income" ? "text-emerald-400" : "text-rose-400"}`}>{item.type === "income" ? "+" : "−"}{money.format(Number(item.amount))}</p>{actions && <div className="hidden gap-1 group-hover:flex"><Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => onEdit(item)}><ChevronDown className="h-4 w-4 rotate-[-90deg]" /></Button><Button variant="ghost" size="icon" className="h-8 w-8 text-rose-400" onClick={() => onDelete(item.id)}><Trash2 className="h-4 w-4" /></Button></div>}</div>; }
function TransactionModal({ form, setForm, categories, onAddCategory, onEditCategory, onDeleteCategory, creditCards, invoicePreview, onSubmit, saving, onClose }: any) { return <div className="fixed inset-0 z-50 grid place-items-end bg-black/60 p-0 backdrop-blur-md sm:place-items-center sm:p-4"><div className="glass-modal w-full max-w-lg rounded-t-3xl border p-5 shadow-2xl sm:rounded-3xl sm:p-6"><div className="mb-5 flex items-start justify-between"><div><p className="text-xs font-medium uppercase tracking-[0.2em] text-primary">Novo movimento</p><h2 className="mt-1 text-xl font-semibold">{form.id ? "Editar lançamento" : "Adicionar lançamento"}</h2></div><Button variant="ghost" size="icon" onClick={onClose}><X className="h-5 w-5" /></Button></div><form onSubmit={onSubmit} className="space-y-4"><div className="grid grid-cols-2 gap-2">{(["income", "expense"] as const).map(type => <button type="button" key={type} onClick={() => setForm({ ...form, type, paymentMethod: type === "expense" ? (form.paymentMethod ?? "cash") : undefined })} className={`rounded-xl border px-3 py-3 text-sm font-medium ${form.type === type ? (type === "income" ? "border-emerald-400/40 bg-emerald-400/10 text-emerald-400" : "border-rose-400/40 bg-rose-400/10 text-rose-400") : "border-white/10 text-muted-foreground"}`}>{type === "income" ? "Entrada" : "Saída"}</button>)}</div>{form.type === "expense" && <div className="space-y-2"><Label>Forma de pagamento</Label><div className="grid grid-cols-2 gap-2 sm:grid-cols-5">{([["cash", "Dinheiro"], ["pix", "Pix"], ["boleto", "Boleto"], ["debit", "Débito"], ["credit", "Crédito"]] as const).map(([value, label]) => <button type="button" key={value} onClick={() => setForm({ ...form, paymentMethod: value, creditCardId: value === "credit" ? form.creditCardId : undefined, installmentsTotal: value === "credit" ? (form.installmentsTotal ?? 1) : undefined })} className={`rounded-xl border px-2 py-2 text-xs font-medium ${form.paymentMethod === value ? "border-primary/50 bg-primary/10 text-primary" : "border-white/10 text-muted-foreground"}`}>{label}</button>)}</div></div>}{form.type === "expense" && form.paymentMethod === "credit" && <div className="grid gap-3 rounded-2xl border border-primary/20 bg-primary/[0.04] p-4 sm:col-span-2 sm:grid-cols-2"><div className="space-y-2"><Label>Cartão cadastrado</Label><select className="h-10 w-full rounded-xl border border-white/10 bg-white/[0.04] px-3 text-sm" value={form.creditCardId ?? ""} onChange={event => setForm({ ...form, creditCardId: event.target.value ? Number(event.target.value) : undefined })}><option value="">Selecione um cartão</option>{creditCards.map((card: CreditCard) => <option key={card.id} value={card.id}>{card.name} · {card.bank}</option>)}</select></div><div className="space-y-2"><Label>Quantidade de parcelas</Label><Input type="number" min="1" step="1" value={form.installmentsTotal ?? 1} onChange={event => setForm({ ...form, installmentsTotal: Math.max(1, Number(event.target.value) || 1) })} /></div>{creditCards.find((card: CreditCard) => card.id === form.creditCardId)?.cardType === "shared" && <div className="space-y-2 sm:col-span-2"><Label>Comprador</Label><select className="h-10 w-full rounded-xl border border-white/10 bg-white/[0.04] px-3 text-sm" value={form.buyer ?? ""} onChange={event => setForm({ ...form, buyer: event.target.value })}><option value="">Selecione o comprador</option>{["LEONARDO", "LEANDRO", "FERLANE", "JOANA", "504", "OUTRO"].map(buyer => <option key={buyer} value={buyer}>{buyer}</option>)}</select>{form.buyer === "OUTRO" && <Input className="mt-2" value={form.customBuyer ?? ""} onChange={event => setForm({ ...form, customBuyer: event.target.value })} placeholder="Digite o nome do comprador" />}</div>}<p className="text-xs text-muted-foreground sm:col-span-2">A fatura será atualizada com o valor total dividido igualmente entre as parcelas.</p>{invoicePreview && <div className="sm:col-span-2 rounded-xl border border-amber-300/20 bg-amber-300/10 px-3 py-2 text-xs text-amber-100"><strong>Esta compra será cobrada na fatura de {invoicePreview.invoiceMonth}.</strong><span className="ml-1 text-amber-100/75">O cartão fecha no dia {invoicePreview.closingDay}; compras a partir desse dia entram na próxima competência.</span></div>}</div>}<div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>{form.type === "income" ? "Fonte pagadora" : "Loja"}</Label><Input value={form.store} onChange={e => setForm({ ...form, store: e.target.value })} placeholder={form.type === "income" ? "Ex.: Empresa, cliente ou instituição" : "Ex.: Mercado Livre"} /></div>{form.type === "expense" && <div className="space-y-2"><Label>Produto</Label><Input value={form.product} onChange={e => setForm({ ...form, product: e.target.value })} placeholder="Ex.: Fone de ouvido" /></div>}<div className="space-y-2"><Label>{form.paymentMethod === "credit" ? "Valor total da compra" : "Valor"}</Label><Input type="number" min="0" step="0.01" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} placeholder="0,00" /></div><div className="space-y-2 sm:col-span-2"><Label>Categoria e ícone</Label><div className="grid grid-cols-2 gap-2 sm:grid-cols-4">{(categories?.length ? categories : [{ label: "Moradia", icon: "⌂" }, { label: "Alimentação", icon: "◒" }, { label: "Transporte", icon: "↗" }, { label: "Lazer", icon: "✦" }, { label: "Salário", icon: "↙" }, { label: "Investimentos", icon: "◈" }]).map((option: LocalCategory) => <button type="button" key={option.label} onClick={() => setForm({ ...form, category: option.label, icon: option.icon })} className={`min-h-10 rounded-xl border px-2 py-2 text-left leading-tight transition ${form.category === option.label ? "border-primary/50 bg-primary/10" : "border-white/10 bg-white/[0.02] hover:bg-white/[0.05]"}`}><span className="mr-2 text-primary">{option.icon}</span><span className="text-xs">{option.label}</span></button>)}</div><Input value={form.category} onChange={e => setForm({ ...form, category: e.target.value, icon: "✦" })} onBlur={() => onAddCategory?.({ label: form.category, icon: form.icon || "✦" })} placeholder="Ou digite uma categoria personalizada" />{categories.filter((option: LocalCategory) => !isDefaultCategory(option.label)).length > 0 && <div className="space-y-1 rounded-xl border border-white/10 bg-white/[0.02] p-2"><p className="text-[11px] text-muted-foreground">Categorias personalizadas</p>{categories.filter((option: LocalCategory) => !isDefaultCategory(option.label)).map((option: LocalCategory) => <div key={option.label} className="flex items-center justify-between gap-2 rounded-lg px-2 py-1.5 text-xs"><span><span className="mr-1.5 text-primary">{option.icon}</span>{option.label}</span><span className="flex gap-1"><Button type="button" variant="ghost" size="icon" className="h-7 w-7" aria-label={`Editar categoria ${option.label}`} onClick={() => { const label = window.prompt("Nome da categoria", option.label); if (label?.trim()) onEditCategory?.(option.label, { label: label.trim(), icon: option.icon }); }}><Pencil className="h-3 w-3" /></Button><Button type="button" variant="ghost" size="icon" className="h-7 w-7 text-rose-400" aria-label={`Excluir categoria ${option.label}`} onClick={() => { if (window.confirm(`Excluir a categoria ${option.label}?`)) onDeleteCategory?.(option.label); }}><Trash2 className="h-3 w-3" /></Button></span></div>)}</div>}</div><div className="space-y-2 sm:col-span-2"><Label>Data</Label><Input type="date" value={form.occurredAt} onChange={e => setForm({ ...form, occurredAt: e.target.value })} /></div></div><Button type="submit" disabled={saving} className="h-11 w-full rounded-xl">{saving ? "Salvando..." : form.id ? "Salvar alterações" : "Adicionar lançamento"}</Button></form></div></div>; }

function QuickOperationDialog({ item, type, onClose, onSubmit }: { item: LocalInvestment; type: InvestmentOperationType; onClose: () => void; onSubmit: (operation: { id: number; type: InvestmentOperationType; quantity: string; price: string; date: string; institution?: string }) => void }) {
  const [quantity, setQuantity] = useState("");
  const [price, setPrice] = useState(String(item.marketPrice ?? item.averagePrice));
  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));
  const title = type === "buy" ? "Nova aplicação" : "Novo resgate";
  return <Dialog open onOpenChange={open => { if (!open) onClose(); }}><DialogContent className="glass-modal max-w-md border-white/15"><DialogHeader><DialogTitle>{title} em {item.ticker || item.name || "ativo"}</DialogTitle><DialogDescription>{type === "buy" ? "Registre uma nova aplicação nesta posição." : `Quantidade disponível: ${Number(item.quantity).toLocaleString("pt-BR")}.`}</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={event => { event.preventDefault(); const parsedQuantity = Number(quantity); const parsedPrice = Number(price); if (!Number.isFinite(parsedQuantity) || parsedQuantity <= 0 || !Number.isFinite(parsedPrice) || parsedPrice < 0 || !date) return; onSubmit({ id: Date.now(), type, quantity: String(parsedQuantity), price: String(parsedPrice), date, institution: item.institution }); }}><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2"><Label>Quantidade</Label><Input type="number" min="0" step="any" value={quantity} onChange={event => setQuantity(event.target.value)} placeholder="0" autoFocus /></div><div className="space-y-2"><Label>Preço por unidade</Label><Input type="number" min="0" step="0.01" value={price} onChange={event => setPrice(event.target.value)} placeholder="0,00" /></div><div className="space-y-2 sm:col-span-2"><Label>Data da movimentação</Label><Input type="date" value={date} onChange={event => setDate(event.target.value)} /></div></div><p className="rounded-xl border border-white/10 bg-white/[0.03] p-3 text-xs text-muted-foreground">Instituição: <strong className="text-foreground">{item.institution || "Não informada"}</strong></p><DialogFooter><Button type="button" variant="ghost" onClick={onClose}>Cancelar</Button><Button type="submit" variant={type === "buy" ? "default" : "destructive"}>{type === "buy" ? "Confirmar aplicação" : "Confirmar resgate"}</Button></DialogFooter></form></DialogContent></Dialog>;
}

function InvestmentsPage(props: any) {
  const [institutionQuery, setInstitutionQuery] = useState("");
  const catalog = investmentInstitutionCatalog(props.investments);
  const filteredInvestments = filterInvestmentsByInstitution(props.investments, institutionQuery);
  const exportInstitutionStatement = async () => {
    if (!filteredInvestments.length) { toast.error("Não há investimentos para exportar neste filtro"); return; }
    const { exportInvestmentInstitutionPdf } = await import("@/lib/financialExports");
    const institution = institutionQuery.trim() || "Todas as instituições";
    exportInvestmentInstitutionPdf({ investments: filteredInvestments, institution });
    toast.success("Extrato de investimentos gerado");
  };
  return <div className="space-y-4"><section className="glass-panel rounded-3xl border p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-end"><div className="min-w-0 flex-1"><Label htmlFor="investment-institution-filter">Buscar por instituição</Label><Input id="investment-institution-filter" className="mt-2" value={institutionQuery} onChange={event => setInstitutionQuery(event.target.value)} placeholder="Ex.: Inter, C6 ou Nomad" list="investment-institution-catalog" /></div><div className="flex flex-wrap gap-2"><Button type="button" variant="outline" onClick={() => setInstitutionQuery("")}>Limpar</Button><Button type="button" variant="outline" onClick={exportInstitutionStatement}><FileText className="mr-1.5 h-4 w-4" />Extrato PDF</Button><select className="h-10 max-w-52 rounded-xl border border-white/10 bg-white/[0.04] px-3 text-sm" value={institutionQuery} onChange={event => setInstitutionQuery(event.target.value)}><option value="">Todas as instituições</option>{catalog.map(institution => <option key={institution} value={institution}>{institution}</option>)}</select></div></div><datalist id="investment-institution-catalog">{catalog.map(institution => <option key={institution} value={institution} />)}</datalist></section><LegacyInvestmentsPage {...props} investments={filteredInvestments} /><InvestmentOperationCardActions investments={filteredInvestments} /></div>;
}

function InvestmentOperationManager({ investments }: { investments: LocalInvestment[] }) {
  const [editing, setEditing] = useState<{ investment: LocalInvestment; operation: { id: number; type: InvestmentOperationType; quantity: string; price: string; date: string; institution?: string } } | null>(null);
  const operations = investments.flatMap(investment => (investment.operations ?? []).map(operation => ({ investment, operation }))).sort((a, b) => b.operation.date.localeCompare(a.operation.date) || b.operation.id - a.operation.id);
  if (!operations.length) return null;
  return <section className="glass-panel rounded-3xl border p-5"><div><h3 className="font-semibold">Movimentações individuais</h3><p className="mt-1 text-xs text-muted-foreground">Edite ou exclua aplicações e resgates sem alterar os demais lançamentos.</p></div><div className="mt-4 space-y-2">{operations.map(({ investment, operation }) => <div key={`${investment.id}-${operation.id}`} className="flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-white/10 bg-white/[0.025] p-3 text-sm"><div><p className="font-medium">{investment.ticker || investment.name || "Ativo"} · <span className={operation.type === "buy" ? "text-emerald-300" : "text-rose-300"}>{operation.type === "buy" ? "Aplicação" : "Resgate"}</span></p><p className="mt-1 text-xs text-muted-foreground">{new Date(`${operation.date}T12:00:00`).toLocaleDateString("pt-BR")} · {Number(operation.quantity).toLocaleString("pt-BR")} × {formatInvestmentMoney(investment, Number(operation.price))}</p></div><div className="flex items-center gap-2"><strong>{formatInvestmentMoney(investment, Number(operation.quantity) * Number(operation.price))}</strong><Button type="button" variant="ghost" size="icon" aria-label="Editar movimentação" onClick={() => setEditing({ investment, operation })}><Pencil className="h-4 w-4" /></Button><Button type="button" variant="ghost" size="icon" className="text-rose-400" aria-label="Excluir movimentação" onClick={() => { if (window.confirm("Excluir esta movimentação?")) window.dispatchEvent(new CustomEvent("findash:investment-operation-delete", { detail: { investmentId: investment.id, operationId: operation.id } })); }}><Trash2 className="h-4 w-4" /></Button></div></div>)}</div>{editing && <Dialog open onOpenChange={open => { if (!open) setEditing(null); }}><DialogContent className="glass-modal max-w-md border-white/15"><DialogHeader><DialogTitle>Editar movimentação</DialogTitle><DialogDescription>{editing.investment.ticker || editing.investment.name || "Ativo"}</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={event => { event.preventDefault(); const form = new FormData(event.currentTarget); const quantity = String(form.get("quantity") ?? ""); const price = String(form.get("price") ?? ""); const date = String(form.get("date") ?? ""); if (!Number.isFinite(Number(quantity)) || Number(quantity) <= 0 || !Number.isFinite(Number(price)) || Number(price) < 0 || !date) return; window.dispatchEvent(new CustomEvent("findash:investment-operation-update", { detail: { investmentId: editing.investment.id, operation: { ...editing.operation, quantity, price, date } } })); setEditing(null); }}><div className="grid gap-3 sm:grid-cols-2"><div className="space-y-2"><Label>Quantidade</Label><Input name="quantity" type="number" min="0" step="any" defaultValue={editing.operation.quantity} /></div><div className="space-y-2"><Label>Preço por unidade</Label><Input name="price" type="number" min="0" step="0.01" defaultValue={editing.operation.price} /></div><div className="space-y-2 sm:col-span-2"><Label>Data</Label><Input name="date" type="date" defaultValue={editing.operation.date} /></div></div><DialogFooter><Button type="button" variant="ghost" onClick={() => setEditing(null)}>Cancelar</Button><Button type="submit">Salvar movimentação</Button></DialogFooter></form></DialogContent></Dialog>}</section>;
}

function LegacyInvestmentsPage({ benchmarks, investments, onAdd, onRefreshQuotes, quotesLoading, refreshingInvestmentTicker, onEdit, onEditInstitution: _onEditInstitution, onDelete, onOperate = (item, type) => window.dispatchEvent(new CustomEvent("findash:investment-operation-start", { detail: { id: item.id, type } })), historyTicker, historyOptions, onHistoryTickerChange, historyData, historyLoading, historyRange, onHistoryRangeChange, historyError }: { benchmarks?: { cdiAnnualRate: number; ipcaAnnualRate: number; cdiDate: string; ipcaDate: string; source: string; fetchedAt: string }; investments: LocalInvestment[]; onAdd: () => void; onRefreshQuotes: (ticker?: string) => void; quotesLoading: boolean; refreshingInvestmentTicker: string | null; onEdit: (item: LocalInvestment) => void; onEditInstitution?: (item: LocalInvestment, detail: any, index: number) => void; onDelete: (id: number) => void; onOperate?: (item: LocalInvestment, type: InvestmentOperationType) => void; historyTicker: string; historyOptions: string[]; onHistoryTickerChange: (ticker: string) => void; historyData: Array<{ date: number; close: number }>; historyLoading: boolean; historyRange: "1mo" | "6mo" | "1y"; onHistoryRangeChange: (range: "1mo" | "6mo" | "1y") => void; historyError?: string }) {
  const [expandedInvestmentId, setExpandedInvestmentId] = useState<number | null>(null);
  const total = investments.reduce((sum, item) => sum + investmentMarketValue(item), 0);
  const cost = investments.reduce((sum, item) => sum + investmentCost(item), 0);
  return <div className="space-y-6"><div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-medium uppercase tracking-[0.24em] text-primary">Patrimônio pessoal</p><h2 className="mt-1 text-2xl font-semibold tracking-tight sm:text-3xl">Sua carteira de investimentos</h2><p className="mt-2 text-sm text-muted-foreground">Cadastre, aplique e resgate diretamente em cada posição.</p></div><div className="flex gap-2"><Button variant="secondary" onClick={() => onRefreshQuotes()} disabled={quotesLoading || !investments.some(item => item.ticker)} className="rounded-xl">{quotesLoading ? <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Atualizando…</> : <><RefreshCw className="mr-2 h-4 w-4" />Atualizar cotações</>}</Button><Button onClick={onAdd} className="rounded-xl"><Plus className="mr-2 h-4 w-4" />Nova posição</Button></div></div><div className="grid gap-4 sm:grid-cols-4"><Metric title="Valor de mercado" value={investments.length ? money.format(total) : "—"} icon={BriefcaseBusiness} accent="text-primary" /><Metric title="Custo total (q × PM)" value={investments.length ? money.format(cost) : "—"} icon={Wallet} accent="text-violet-300" /><Metric title="Posições" value={String(investments.length)} icon={Landmark} accent="text-emerald-400" /><Metric title="Categorias usadas" value={String(new Set(investments.map(item => item.category)).size)} icon={Coins} accent="text-amber-300" /></div><AssetPerformanceChart ticker={historyTicker} options={historyOptions} onTickerChange={onHistoryTickerChange} data={historyData} loading={historyLoading} range={historyRange} onRangeChange={onHistoryRangeChange} error={historyError} /><section className="glass-panel rounded-3xl border p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h3 className="font-semibold">Ativos cadastrados</h3><p className="mt-1 text-xs text-muted-foreground">Renda fixa, variável, fundos, dólar e cripto.</p></div><Button variant="secondary" size="sm" onClick={onAdd}><Plus className="mr-2 h-4 w-4" />Adicionar</Button></div>{investments.length ? <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{investments.map(item => { const category = investmentCategories.find(option => option.value === item.category); const profitability = investmentProfitability(item); const movements = [...(item.operations ?? [])].filter(operation => Number(operation.quantity) > 0 && Number(operation.price) >= 0).sort((a, b) => b.date.localeCompare(a.date) || b.id - a.id); const expanded = expandedInvestmentId === item.id; return <article key={item.id} className="rounded-2xl border border-white/10 bg-white/[0.025] p-4"><div className="flex items-start justify-between gap-3"><div className="flex min-w-0 items-center gap-3"><img src={item.ticker ? `https://assets.parqet.com/logos/stocks/${encodeURIComponent(item.ticker.toUpperCase())}.png` : undefined} alt="" aria-hidden="true" className="h-9 w-9 rounded-xl border border-white/10 bg-white/[0.04] object-contain p-1" onError={event => { event.currentTarget.style.display = "none"; }} /><div className="min-w-0"><p className="font-medium">{item.ticker || item.name || "Ativo"}</p><p className="text-xs text-muted-foreground">{item.ticker || "Sem ticker"} · {category?.label}</p></div></div><div className="flex gap-1">{movements.length > 0 && <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => setExpandedInvestmentId(expanded ? null : item.id)} aria-label="Ver movimentações" title="Ver movimentações"><ChevronDown className={`h-3.5 w-3.5 transition-transform ${expanded ? "rotate-180" : ""}`} /></Button>}<Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => onRefreshQuotes(item.ticker)} disabled={quotesLoading} aria-label="Atualizar cotação deste ativo" title="Atualizar cotação"><RefreshCw className={`h-3.5 w-3.5 ${refreshingInvestmentTicker === item.ticker.toUpperCase() ? "animate-spin" : ""}`} /></Button><Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => onEdit(item)} aria-label="Editar posição"><Pencil className="h-3.5 w-3.5" /></Button><Button variant="ghost" size="icon" className="h-8 w-8 text-rose-400" onClick={() => onDelete(item.id)} aria-label="Excluir posição"><Trash2 className="h-3.5 w-3.5" /></Button></div></div><p className="mt-5 text-xl font-semibold">{formatInvestmentMoney(item, investmentMarketValue(item))}</p><p className="mt-1 text-xs text-muted-foreground">Quantidade: {Number(item.quantity).toLocaleString("pt-BR")} · PM: {formatInvestmentMoney(item, Number(item.averagePrice))}</p><p className="mt-1 text-xs text-muted-foreground">Custo consolidado: {formatInvestmentMoney(item, investmentCost(item))}</p><p className={`mt-1 text-xs font-medium ${profitability.percent >= 0 ? "text-emerald-400" : "text-rose-400"}`}>Rentabilidade: {profitability.percent >= 0 ? "+" : ""}{profitability.percent.toFixed(2)}%</p>{profitability.contractedAnnualPercent > 0 && <UiTooltip><TooltipTrigger asChild><p tabIndex={0} className="mt-1 inline-flex cursor-help text-xs text-violet-300 outline-none focus-visible:rounded focus-visible:ring-2 focus-visible:ring-primary">Contratada estimada: {profitability.contractedAnnualPercent.toFixed(2)}% a.a. · {formatInvestmentMoney(item, profitability.contractedProfit)}</p></TooltipTrigger><TooltipContent className="max-w-xs text-xs">{item.contractedBenchmark === "IPCA+" ? `Taxa total estimada = ${Number(item.contractedRate ?? 0).toFixed(2)}% real contratada + ${Number(item.benchmarkAnnualRate ?? 0).toFixed(2)}% de IPCA anual do Banco Central.` : item.contractedBenchmark === "CDI" ? `${Number(item.contractedRate ?? 0).toFixed(2)}% do CDI anualizado (${Number(item.benchmarkAnnualRate ?? 0).toFixed(2)}%).` : "Taxa anual contratada informada para esta posição."}</TooltipContent></UiTooltip>}<p className="mt-1 text-xs text-muted-foreground">{item.quoteError ? `Cotação indisponível: ${item.quoteError}` : item.quoteFetchedAt ? `Cotação ${item.quoteSource ?? "externa"} · ${new Date(item.quoteFetchedAt).toLocaleString("pt-BR")}` : item.category === "fixed-income" ? "Rendimento calculado pela taxa contratada" : "Sem cotação automática"}</p><p className="mt-1 text-xs text-muted-foreground">{item.institution || "Instituição não informada"}</p><div className="mt-4 grid grid-cols-2 gap-2"><Button size="sm" variant="secondary" onClick={() => onOperate(item, "buy")}><CircleArrowDown className="mr-1.5 h-4 w-4 text-emerald-300" />Aplicar</Button><Button size="sm" variant="outline" disabled={Number(item.quantity) <= 0} onClick={() => onOperate(item, "sell")}><CircleArrowUp className="mr-1.5 h-4 w-4 text-rose-300" />Resgatar</Button></div>{movements.length > 0 && <div className="mt-3 border-t border-white/8 pt-3"><button type="button" className="text-xs font-medium text-primary hover:underline" onClick={() => setExpandedInvestmentId(expanded ? null : item.id)}>{expanded ? "Ocultar movimentações" : `Ver ${movements.length} movimentação(ões)`}</button>{expanded && <div className="mt-2 space-y-2">{movements.map(operation => <div key={`${item.id}-${operation.id}`} className="flex items-center justify-between gap-3 rounded-xl bg-white/[0.03] p-3 text-xs"><div><p className={`font-medium ${operation.type === "buy" ? "text-emerald-300" : "text-rose-300"}`}>{operation.type === "buy" ? "Aplicação" : "Resgate"}</p><p className="mt-1 text-muted-foreground">{new Date(`${operation.date}T12:00:00`).toLocaleDateString("pt-BR")} · {Number(operation.quantity).toLocaleString("pt-BR")} × {formatInvestmentMoney(item, Number(operation.price))}</p></div><strong>{formatInvestmentMoney(item, Number(operation.quantity) * Number(operation.price))}</strong></div>)}</div>}</div>}</article>; })}</div> : <div className="rounded-2xl border border-dashed border-white/10 p-10 text-center"><BriefcaseBusiness className="mx-auto h-8 w-8 text-primary" /><p className="mt-3 text-sm text-muted-foreground">Sua carteira ainda está vazia.</p><Button variant="secondary" className="mt-4" onClick={onAdd}><Plus className="mr-2 h-4 w-4" />Cadastrar primeiro ativo</Button></div>}</section></div>;
}

function InvestmentModal({ benchmarks, form, setForm, onSubmit, onClose }: any) { return <div className="fixed inset-0 z-50 grid place-items-end bg-black/60 p-0 backdrop-blur-md sm:place-items-center sm:p-4"><div className="glass-modal max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-t-3xl border p-5 shadow-2xl sm:rounded-3xl sm:p-6"><div className="mb-5 flex items-start justify-between"><div><p className="text-xs font-medium uppercase tracking-[0.2em] text-primary">Carteira</p><h2 className="mt-1 text-xl font-semibold">{form.id ? (form.institutionDetailIndex !== undefined ? "Editar instituição" : "Editar posição") : "Cadastrar investimento"}</h2></div><Button variant="ghost" size="icon" onClick={onClose}><X className="h-5 w-5" /></Button></div><form onSubmit={onSubmit} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><div className="space-y-2 sm:col-span-2"><Label>Operação</Label><div className="grid grid-cols-2 gap-2">{([['buy', 'Compra'], ['sell', 'Venda']] as const).map(([value, label]) => <button type="button" key={value} onClick={() => setForm({ ...form, operationType: value })} className={`rounded-xl border px-3 py-3 text-sm font-medium ${form.operationType === value ? (value === 'buy' ? 'border-emerald-400/40 bg-emerald-400/10 text-emerald-400' : 'border-rose-400/40 bg-rose-400/10 text-rose-400') : 'border-white/10 text-muted-foreground'}`}>{label}</button>)}</div></div><div className="space-y-2"><Label>Ticker ou código</Label><Input value={form.ticker} onChange={e => setForm({ ...form, ticker: e.target.value.toUpperCase() })} placeholder="Ex.: BOVA11, CDB" /></div><div className="space-y-2"><Label>Instituição</Label><Input value={form.institution} onChange={e => setForm({ ...form, institution: e.target.value })} placeholder="Ex.: Banco ou corretora" /></div><div className="space-y-2 sm:col-span-2"><Label>Categoria</Label><div className="grid gap-2 sm:grid-cols-2">{investmentCategories.map(option => <button type="button" key={option.value} onClick={() => setForm({ ...form, category: option.value })} className={`rounded-xl border p-3 text-left transition ${form.category === option.value ? "border-primary/50 bg-primary/10" : "border-white/10 bg-white/[0.02] hover:bg-white/[0.05]"}`}><p className="text-sm font-medium">{option.label}</p><p className="mt-1 text-xs text-muted-foreground">{option.detail}</p></button>)}</div></div><div className="space-y-2"><Label>Quantidade</Label><Input type="number" min="0" step="any" value={form.quantity} onChange={e => setForm({ ...form, quantity: e.target.value })} placeholder="0" /></div><div className="space-y-2"><Label>Preço da operação / PM</Label><Input type="number" min="0" step="0.01" value={form.averagePrice} onChange={e => setForm({ ...form, averagePrice: e.target.value })} placeholder="0,00" /></div><div className="space-y-2"><Label>Data da operação</Label><Input type="date" value={form.operationDate} onChange={e => setForm({ ...form, operationDate: e.target.value })} /></div>{(form.category === "fixed-income" || form.category === "treasury") && <div className="sm:col-span-2 rounded-2xl border border-violet-300/15 bg-violet-300/[0.04] p-4"><p className="text-sm font-medium">Rentabilidade contratada</p><p className="mt-1 text-xs text-muted-foreground">Para Tesouro Direto, CDI e IPCA são preenchidos automaticamente com os indicadores atuais do Banco Central.</p><div className="mt-3 grid gap-3 sm:grid-cols-3"><div className="space-y-2"><Label>Benchmark</Label><select className="h-10 w-full rounded-xl border border-white/10 bg-white/[0.04] px-3 text-sm" value={form.contractedBenchmark} onChange={e => { const value = e.target.value as ContractedBenchmark; const benchmarkAnnualRate = value === "CDI" ? String(benchmarks?.cdiAnnualRate?.toFixed(2) ?? "") : value === "IPCA+" ? String(benchmarks?.ipcaAnnualRate?.toFixed(2) ?? "") : form.benchmarkAnnualRate; setForm({ ...form, contractedBenchmark: value, benchmarkAnnualRate }); }}><option value="none">Sem benchmark</option><option value="CDI">CDI</option><option value="IPCA+">IPCA+</option><option value="Prefixado">Prefixado</option></select></div><div className="space-y-2"><Label>{form.contractedBenchmark === "Prefixado" ? "Taxa anual (%)" : "Percentual (%)"}</Label><Input type="number" min="0" step="0.01" value={form.contractedRate} onChange={e => setForm({ ...form, contractedRate: e.target.value })} placeholder={form.contractedBenchmark === "CDI" ? "100" : "0"} /></div><div className="space-y-2"><Label>Taxa atual do benchmark (%)</Label><Input type="number" min="0" step="0.01" value={form.benchmarkAnnualRate} readOnly={form.contractedBenchmark === "CDI" || form.contractedBenchmark === "IPCA+"} onChange={e => setForm({ ...form, benchmarkAnnualRate: e.target.value })} placeholder="Ex.: 10,50" /></div>{(form.contractedBenchmark === "CDI" || form.contractedBenchmark === "IPCA+") && <p className="mt-2 text-[11px] text-muted-foreground">{benchmarks ? `${benchmarks.source} · atualizado em ${new Date(benchmarks.fetchedAt).toLocaleString("pt-BR")}` : "Consultando indicadores atuais…"}</p>}</div></div>}<div className="rounded-xl border border-dashed border-white/10 bg-white/[0.02] p-3 text-xs text-muted-foreground"><p className="font-medium text-foreground">Valor atual automático</p><p className="mt-1">O ticker identifica o ativo e a cotação atualiza o valor de mercado. A edição salva os dados da posição sem criar uma nova operação.</p></div><div className="space-y-2"><Label>Observações</Label><Input value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Opcional" /></div></div><Button type="submit" className="h-11 w-full rounded-xl">{form.id ? "Salvar alterações" : "Cadastrar posição"}</Button></form></div></div>; }
